@Injectable()
export class MasterApi {
  private useAxios = false;

  private readonly masterApiAppId: string;

  public constructor(
    private readonly daprClient: DaprClient,
    private readonly daprConfigService: DaprConfigService,
    private readonly customLogger: AppLogger,
  ) {
    this.masterApiAppId = this.daprConfigService.masterApiAppId;
  }

  public async fetchPoolstockByStorageLocation(
    requestDto: StorageLocationRequestDto,
  ): Promise<PoolstockResponse | undefined> {
    const context: JobsLogContext = {
      method: 'fetchPoolstockByStorageLocation',
      object: requestDto.storageLocation,
      plant: requestDto.plant,
      service: 'MasterApi',
    };

    const result = await invokeService<PoolstockResponse>(
      {
        context,
        customLogger: this.customLogger,
        daprClient: this.daprClient,
      },
      {
        serviceAppId: this.masterApiAppId,
        serviceMethod: `storage-location/PoolstockByStorageLocation/${requestDto.plant}/${requestDto.storageLocation}`,
        method: HttpMethod.GET,
      },
    );
    return result;
  }

  public async fetchStorageLocationTypeByPlantAndId(
    plant: number,
    storageLocationId: Array<string>,
  ): Promise<StorageLocationTypeMap | undefined> {
    const context: JobsLogContext = {
      method: 'fetchStorageLocationTypeByPlantAndId',
      plant,
      service: 'MasterApi',
    };
    const result = await invokeService<StorageLocationTypeMap>(
      {
        context,
        customLogger: this.customLogger,
        daprClient: this.daprClient,
      },
      {
        serviceAppId: this.masterApiAppId,
        serviceMethod: `storage-location/${plant}/${storageLocationId}/type`,
        method: HttpMethod.GET,
      },
    );
    return result;
  }

  public async fetchStorageLocationListTypeByPlantAndId(
    plant: number,
    storageLocationId: Array<string>,
  ): Promise<Record<string, string> | undefined> {
    const context: JobsLogContext = {
      method: 'fetchStorageLocationTypeByPlantAndId',
      plant,
      service: 'MasterApi',
    };
    const requestDto = {
      plant,
      storageLocationId,
    };
    const result = await invokeService<Record<string, string>>(
      {
        context,
        customLogger: this.customLogger,
        daprClient: this.daprClient,
      },
      {
        data: requestDto,
        method: HttpMethod.POST,
        serviceAppId: this.masterApiAppId,
        serviceMethod: 'storage-location/type',
        useAxios: this.useAxios,
      },
    );
    return result ?? {};
  }

  public setUseAxios(useAxios: boolean): void {
    this.useAxios = useAxios;
  }
}

import { HttpMethod } from '@dapr/dapr';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import axios from 'axios';
import { DaprClient } from 'dapr-client';
import { DaprConfigService } from 'src/config/dapr/dapr-config.service';
import { MinSeqNumberRequestDto } from 'src/dtos/min-seq-number-request.dto';
import { MinSeqNumberResponse } from 'src/interface/min-seq-number-response';
import {
  OrderResponse,
  PickingOrderList,
  BufferOrderResponse,
} from 'src/interface/picking-order-list';
import { BufferWkResponse } from '../interface/buffer-wk-list';
import { AppLogger } from '@/common/logger/app-logger';
import { MaterialRequestDto } from '@/dtos/material-request.dto';
import { invokeService } from '@/helpers/invokes/invoke-service';
import { MaterialResponse } from '@/interface/material-response';
import { SebangoByMaterialDtlByIdsRequestDTO } from '@/interface/sebango-by-material-dtl-by-ids-request.dto';

@Injectable()
export class OrderApi {
  private useAxios = false;

  private readonly orderApiAppId: string;

  public constructor(
    private readonly daprClient: DaprClient,
    private readonly daprConfigService: DaprConfigService,
    private readonly customLogger: AppLogger,
  ) {
    this.orderApiAppId = this.daprConfigService.orderApiAppId;
  }

  public async fetchMinSeqNum(
    requestDto: MinSeqNumberRequestDto,
  ): Promise<MinSeqNumberResponse | undefined> {
    const context: JobsLogContext = {
      method: 'fetchMinSeqNum',
      object: requestDto.relatedOrder,
      plant: requestDto.plant,
      service: 'OrderApi',
    };
    const serviceMethod = `production-order/minSeqNumByPickingOrder/${requestDto.plant}/${requestDto.relatedOrder}`;
    const result = await invokeService<MinSeqNumberResponse>(
      {
        context,
        customLogger: this.customLogger,
        daprClient: this.daprClient,
      },
      {
        serviceAppId: this.orderApiAppId,
        serviceMethod,
        method: HttpMethod.GET,
      },
    );
    return result;
  }

  public async fetchOrdersByDate(
    plant: number,
    date: Date,
  ): Promise<OrderResponse | undefined> {
    const context: JobsLogContext = {
      method: 'fetchOrdersByDate',
      object: date.toString(),
      plant,
      service: 'OrderApi',
    };

    const serviceAppId = this.daprConfigService.orderApiAppIdInternal;
    const serviceMethodSeqnum = `picking-order/orders-with-reschudeling-version-triggers/${plant}/${date.toISOString()}`;
    const url = `${serviceAppId}/${serviceMethodSeqnum}`;

    try {
      const response = await axios.get(url, {
        headers: {
          authorization: `Bearer ${process.env.TOKEN}`,
        },
      });
      const serverUTCDateTime = response.headers['date'];

      const result = response.data ?? [];
      const headers: Record<string, string> = {};
      headers['date'] = serverUTCDateTime;
      return {
        result: result as Array<PickingOrderList>,
        headers,
      };
    } catch (error) {
      this.customLogger.error(
        `Error in fetchOrdersByDate Plant ${plant}: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }

  public async fetchBufferOrdersByDate(
    plant: number,
