    const serviceMethodPath = `picking-order/get-wk-by-od-plant?plant=${plant}&outbound=${outbound}`;
    const result = await invokeService<Array<PickingOrderList>>(
      {
        context,
        customLogger: this.customLogger,
        daprClient: this.daprClient,
