import { Module } from '@nestjs/common';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';

@Module({
  exports: [MutexManagerService],
  providers: [MutexManagerService],
})
export class MutexManagerModule {}

import { Mutex } from 'async-mutex';

export class MutexManagerService {
  private readonly mutexes: Map<string, { mutex: Mutex; lastUsed: number }>;

  private readonly cleanupInterval: number; // In milliseconds

  private readonly cleanupThreshold: number; // Inactivity time threshold

  public constructor(cleanupInterval = 60_000, cleanupThreshold = 300_000) {
    // 60 seconds, 5 minutes threshold
    this.mutexes = new Map();
    this.cleanupInterval = cleanupInterval;
    this.cleanupThreshold = cleanupThreshold;
    this.startCleanupThread();
  }

  // Get or create a mutex for a given cacheKey
  public getMutex(cacheKey: string): Mutex {
    let mutexEntry = this.mutexes.get(cacheKey);
    if (mutexEntry) {
      mutexEntry.lastUsed = Date.now(); // Update the last used timestamp
    } else {
      mutexEntry = { lastUsed: Date.now(), mutex: new Mutex() };
      this.mutexes.set(cacheKey, mutexEntry);
    }
    return mutexEntry.mutex;
  }

  // Start a cleanup thread to remove inactive mutexes
  private startCleanupThread(): void {
    setInterval(() => {
      const now = Date.now();
      for (const [key, entry] of this.mutexes.entries()) {
        if (now - entry.lastUsed > this.cleanupThreshold) {
          this.mutexes.delete(key); // Remove inactive mutex
        }
      }
    }, this.cleanupInterval);
  }
}

