      const secret = await client.secret.get(store, name);
      return Object.values(secret)[0];
    } catch (error) {
      this.customLogger.error(
        'Error while getting Main Access Key',
        this.context,
        error,
      );
      throw new Error('Failed to retrieve Main Access Key');
    }
  }

