    }> = [
      {
        key: 'redisHostManagedRedis',
        value: this.redisHostManagedRedis,
      },
      {
        key: 'redisPortManagedRedis',
        value: this.redisPortManagedRedis,
      },
      {
        key: 'statePrefix',
        value: this.statePrefix,
      },
      {
        key: 'mainSecretStore',
        value: this.daprSecretStore,
      },
    ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }
    const hasUsernameAndPassword = this.username && this.localRedisPassword;
    const hasManagedIdentity = await this.getAzureTokenWithExpiry();

    if (!hasUsernameAndPassword && !hasManagedIdentity.token) {
      this.customLogger.error('Either username/password', context);
      throw new Error(
        'Configuration error: You must set either username/password',
      );
    }
  }
}

