  public async upsertBatchWksBuffer(
    shopOrders: Array<BufferWkResponse>,
  ): Promise<void> {
    if (shopOrders.length === 0) return;

    const context: JobsLogContext = {
      method: 'upsertBatchWksBuffer',
      plant: shopOrders[0].plant,
      service: 'CosmosDatabaseService',
    };

    try {
      await pMap(
        shopOrders,
        async (order) => {
          const orderWithId = {
            ...order,
            id: order.shopOrder,
            plant: order.plant,
          };

          try {
            await this.container.items.upsert(orderWithId);
          } catch (error) {
            this.customLogger.error(
              `Failed to upsert order with ID ${orderWithId.id}`,
              context,
              error,
            );
            throw error;
          }
        },
        {
          concurrency: 5, // Safe low concurrency; adjust 5–10 depending on load
        },
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting shop orders into Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async upsertBatchShopOrders(
    shopOrders: Array<ShopOrder>,
