      method: 'deleteShopOrders',
      plant: Number(partitionKey),
      service: 'CosmosDatabaseService',
    };
    try {
      const deletePromises = shopOrderIds.map((id) =>
        this.container
          .item(id.pickingOrderId, id.plant)
          .delete()
          .catch((error) => {
            if (error.code === 404 || error.statusCode === 404) return;
            throw error; // Bubble up for outer catch to log
          }),
      );

      await Promise.all(deletePromises);
    } catch (error) {
      this.customLogger.error(
        `Plant ${partitionKey} error deleting shop orders from Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  public async getShopOrdersCountByPlantList(): Promise<Map<string, number>> {
    const context: JobsLogContext = {
      method: 'getShopOrdersCountByPlantList',
      service: 'CosmosDatabaseService',
    };

    try {
      // Convert plantList into a string array for use in the query
      let where = ``;
      if (this.fieldToBeChecked !== '') {
        where = ` WHERE NOT IS_DEFINED(c.${this.fieldToBeChecked}) `;
      }
      const querySpec = {
        query: `SELECT c.plant, COUNT(1) AS orderCount FROM c ${where}  GROUP BY c.plant`,
      };
      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();
      // Convert the result into a Map
      const plantCounts = new Map<string, number>();
      for (const row of resources) {
        const { plant, orderCount } = row;
        plantCounts.set(plant, orderCount);
      }
      return plantCounts;
    } catch (error) {
      this.customLogger.error(
        `Error fetching shop orders count for plants: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async getPlantList(): Promise<Array<string>> {
    const context: JobsLogContext = {
      method: 'getPlantList',
