        query: 'SELECT DISTINCT c.plant FROM c', // Modify this query according to your schema
      };
      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();
      // Assuming each document has a 'plant' field and you want to return an array of plant names/IDs
      const plantList = resources.map((item) => item.plant);
      return plantList;
    } catch (error) {
      this.customLogger.error(
        `Error fetching plant list: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async getPaginatedShopOrders(
