    plant: number,
  ): Promise<Array<ShopOrder>> {
    const context: JobsLogContext = {
      method: 'getPaginatedShopOrders',
      service: 'CosmosDatabaseService',
    };

    try {
      // Cosmos DB query using OFFSET and LIMIT for pagination
      let where = '';
      if (this.fieldToBeChecked !== '') {
        where = ` AND  NOT IS_DEFINED(c.${this.fieldToBeChecked}) `;
      }
      const querySpec = {
        parameters: [
          { name: '@offset', value: offset },
          { name: '@limit', value: limit },
          { name: '@plant', value: plant },
        ],
        query: `SELECT * FROM c WHERE c.plant = @plant ${where}  ORDER BY c._ts OFFSET @offset LIMIT @limit`,
      };

      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();
      // Return the nextToken and the fetched orders
      return resources;
    } catch (error) {
      this.customLogger.error(
        `Error fetching paginated shop orders: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async updateWithBatch(shopOrders: Array<ShopOrder>): Promise<void> {
    const context: JobsLogContext = {
      method: 'updateWithBatch',
      plant: shopOrders[0]?.plant,
      service: 'CosmosDatabaseService',
    };

    try {
      // Convert Date fields to strings before upsertin
      // Prepare bulk upsert operations
      const upsertOperations: Array<ReplaceOperationInput> = shopOrders.map(
        (order) => {
