            operationType: BulkOperationType.Replace,
            partitionKey: order.plant, // Ensure correct partitioning
            resourceBody: orderWithId,
          };
        },
      );

      // Perform bulk upsert
      for (let index = 0; index < upsertOperations.length; index += 100) {
        const chunk = upsertOperations.slice(index, index + 100);
        const response = await this.container.items.bulk(chunk);
        // Optionally handle the response
      }
