  public async deleteIfExistsByIds(
    ids: Array<string>,
    partitionKey: number,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'deleteIfExistsByIds',
      plant: partitionKey,
      service: 'CosmosDatabaseService',
    };

    try {
      if (ids.length === 0) {
        return;
      }

      const existingIds: Set<string> = new Set();
      const existenceChunkSize = 1000;

      // Step 1: Chunk the IDs for existence check
      const existenceChunks = Array.from(
        { length: Math.ceil(ids.length / existenceChunkSize) },
        (_, index) =>
          ids.slice(
            index * existenceChunkSize,
            (index + 1) * existenceChunkSize,
          ),
      );

      // Step 2: Use pMap to query existence in parallel (adjust concurrency as needed)
      await pMap(
        existenceChunks,
        async (chunk) => {
          const parameterNames = chunk.map((_, index) => `@id${index}`);
          const queryText = `SELECT c.id FROM c WHERE c.id IN (${parameterNames.join(',')})`;
          const parameters = chunk.map((id, index) => ({
            name: `@id${index}`,
            value: id,
          }));

          const query = {
            query: queryText,
            parameters,
          };

          const { resources } = await this.container.items
            .query(query, { partitionKey })
            .fetchAll();

          for (const document of resources) {
            existingIds.add(document.id);
          }
        },
        { concurrency: 1 }, // You can adjust this safely
      );

      if (existingIds.size === 0) {
        return;
      }

      // Step 3: Prepare delete operations from existing IDs
      const deleteOperations = ids
        .filter((id) => existingIds.has(id))
        .map((id) => ({
          id,
          operationType: BulkOperationType.Delete,
          partitionKey,
        }));

      const deleteChunkSize = 100;
      const deleteChunks = Array.from(
        { length: Math.ceil(deleteOperations.length / deleteChunkSize) },
        (_, index) =>
          deleteOperations.slice(
            index * deleteChunkSize,
            (index + 1) * deleteChunkSize,
          ),
      );

      // Step 4: Delete using pMap
      await pMap(
        deleteChunks,
        async (chunk) => {
          const response = await this.container.items.bulk(chunk);
          // Add a 2-second delay after processing each chunk
          await new Promise<void>((resolve) => {
            setTimeout(() => {
              resolve();
            }, 1000);
          });
        },
        { concurrency: 1 }, // Increase if safe for your Cosmos setup
      );
    } catch (error) {
      this.customLogger.error(
        `Error during conditional deletion in Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async getEtagsByIds(
    ids: Array<string>, // Array of IDs
    plant: number, // Plant number to filter by
  ): Promise<Record<string, string> | undefined> {
    // Return type as Record<string, string>
    const context: JobsLogContext = {
      method: 'getEtagsByIds',
      service: 'CosmosDatabaseService',
    };

    const result: Record<string, string> = {}; // Initialize as an object

    try {
      if (ids.length === 0) {
        return result; // Return an empty object if no IDs provided
      }

      // Prepare parameters for the query

      // Add the plant parameter

      const inClause = ids.map((id) => `'${id}'`).join(', ');

      // Cosmos DB query with the plant and IDs filter
      const querySpec = {
        query: `SELECT c.id, c._etag as etag  FROM c WHERE c.id IN (${inClause}) AND c.plant = ${plant}`,
      };
      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      // Populate result object with id and etag
      for (const item of resources) {
        result[item.id] = item.etag;
      }

      return result; // Return the record (object)
    } catch (error) {
      this.customLogger.error(
        `Error fetching etags by IDs for plant ${plant}: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }

  public async replaceUpdatesByWksByBatch(
    plant: number,
    wksToBeUpdated: Record<string, OrderUpdate>,
  ): Promise<void> {
    const wkIds = Object.keys(wksToBeUpdated); // ✅ dynamically get all WKS IDs

    await pMap(
      wkIds,
      async (id) => {
        const updates = wksToBeUpdated[id]?.updates ?? {};
        const { resource: existingDocument } = await this.container
          .item(id, plant)
          .read();
        if (existingDocument) {
          const patchOperations: Array<PatchOperation> = Object.entries(
            updates,
          ).map(
            ([key, value]) =>
              ({
                op: 'set',
                path: `/${key}`,
                value,
              }) as PatchOperation,
          );

          try {
            await this.container.item(id, plant).patch(patchOperations);
          } catch (error) {
            if (error.code === 404) {
              this.customLogger.warn(
                `wk ${id} not found, skipping`,
                error.message,
              );
            } else {
              this.customLogger.error(
                `error in patching wk ${id}, skipping`,
                error.message,
              );
            }
          }
        }
      },
      { concurrency: 5 }, // Parallel patching
    );
  }
}

