import { InvokerOptions } from '@dapr/dapr';

/**
 * Builds options for Dapr invoker.
 * @returns - Options for Dapr invoker
 */
export function buildInvokeOptions(): InvokerOptions {
  const options: InvokerOptions = {};

  if (process.env.TOKEN) {
    options.headers = { authorization: `Bearer ${process.env.TOKEN}` };
  }

  return options;
}

import { JobsLogContext } from '@mesx/common-lib';
import axios from 'axios';
import { DaprClient, HttpMethod } from 'dapr-client';
import { buildInvokeOptions } from './build-invoke-options';
import { AppLogger } from '@/common/logger/app-logger';
import { RequestHeadersDto } from '@/dtos/request-headers.dto';

/**
 * Invokes a service using Dapr client.
 * @param serviceContext - Context for the service invocation, including Dapr client and logger.
 * @param serviceContext.context - The context for the service.
 * @param serviceContext.customLogger - The custom logger instance.
 * @param serviceContext.daprClient - The Dapr client instance.
 * @param requestContext - Context for the request, including service ID, method, HTTP method, data, and options.
 * @param requestContext.serviceAppId - The ID of the service to invoke.
 * @param requestContext.serviceMethod - The method to invoke on the service.
 * @param requestContext.method - The HTTP method to use for the invocation.
 * @param requestContext.data - The data to send with the request.
 * @param requestContext.useAxios defaults to false
 * @param requestContext.options - Optional settings for the request, including headers and error handling.
 * @param requestContext.options.headers - Optional headers to include in the request.
 * @param errorHandling - Optional error handling settings.
 * @param errorHandling.throwIfError - Whether to throw an error if the invocation fails.
 * @param errorHandling.customError - A custom error to throw if the invocation fails.
 * @returns The response from the invoked service, or undefined if an error occurred and throwIfError is false.
 * @throws Error if the invocation fails and throwIfError is true.
 */
export async function invokeService<T>(
  serviceContext: {
    context: JobsLogContext;
    customLogger: AppLogger;
    daprClient: DaprClient;
  },
  requestContext: {
    serviceAppId: string;
    serviceMethod: string;
    method: HttpMethod;
    data?: object;
    useAxios?: boolean;
    options?: {
      headers?: Record<string, unknown> | RequestHeadersDto;
    };
  },
  errorHandling?: {
    throwIfError?: boolean;
    customError?: Error;
  },
): Promise<T | undefined> {
  const { context, customLogger, daprClient } = serviceContext;
  const {
    serviceAppId,
    serviceMethod,
    method,
    data,
    useAxios = false, // Default: use Dapr
    options,
  } = requestContext;

  const { headers } = options || {};

  try {
    const invokeOptions = headers ? { headers } : buildInvokeOptions();

    if (useAxios) {
      const url = `${serviceAppId}/${serviceMethod}`;
      const axiosConfig = { headers: headers as Record<string, string> };
      axiosConfig.headers = invokeOptions.headers as Record<string, string>;
      let response;
      switch (method) {
        case HttpMethod.GET: {
          response = await axios.get<T>(url, axiosConfig);
          break;
        }
        case HttpMethod.POST: {
          response = await axios.post<T>(url, data, axiosConfig);
          break;
        }
        case HttpMethod.PUT: {
          response = await axios.put<T>(url, data, axiosConfig);
          break;
        }
        case HttpMethod.DELETE: {
          response = await axios.delete<T>(url, axiosConfig);
          break;
        }
        default: {
          throw new Error(`Unsupported HTTP method: ${method}`);
        }
      }

      return response.data;
    }
    const response = await daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      method,
      data,
      invokeOptions,
    );
    return response as T;
  } catch (error) {
    customLogger.error(
      `Error in ${context.method}: ${error.message}`,
      context,
      error.stack,
    );

    if (errorHandling?.throwIfError) {
      if (errorHandling?.customError) throw errorHandling?.customError;
      throw error;
    }

    return undefined;
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { withTimeout, E_TIMEOUT, MutexInterface } from 'async-mutex';
import { AppLogger } from '@/common/logger/app-logger';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';
import { asyncSleep } from '@/common/sleep/sleep';

/**
 * Acquire a lock with timeout and retries
 * @param logger Application logger
 * @param queueKey Queue key to get the right mutex instance
 * @param serviceMutexes Mutexes for the services
 * @param timeoutMs Lock acquiring timeout in milliseconds
 * @param retryCount Number of retry attempts
 * @param retryDelayMs Delay between retries in milliseconds
 * @returns Releaser function
 */
export async function acquireLockWithTimeout(
  logger: AppLogger,
  queueKey: string,
  serviceMutexes: MutexManagerService,
  timeoutMs = 1000,
  retryCount = 3,
  retryDelayMs = 1000,
): Promise<MutexInterface.Releaser | undefined> {
  let lastError: Error | undefined;
  let attempt = 1;

  const acquireLock = async (): Promise<
    MutexInterface.Releaser | undefined
  > => {
    const context: JobsLogContext = {
      method: 'acquireLock',
      service: 'acquireLockWithTimeout',
    };
    try {
      const mutex = serviceMutexes.getMutex(queueKey);
      return await withTimeout(mutex, timeoutMs).acquire();
    } catch (error) {
      lastError = error;
      if (error === E_TIMEOUT) {
        logger.warn(
          `Timeout while acquiring lock for ${queueKey} (Attempt ${attempt} of ${retryCount})`,
          context,
        );
      } else {
        logger.error(
          `Error acquiring lock for ${queueKey} (Attempt ${attempt} of ${retryCount}): ${error.message}`,
          context,
          error.stack,
        );
      }
      if (attempt < retryCount) {
        await asyncSleep(retryDelayMs);
        attempt += 1;
        return acquireLock();
      }
    }

    // Log the final failure
    if (lastError) {
      logger.error(
        `Failed to acquire lock for ${queueKey} after ${retryCount} attempts: ${lastError.message}`,
        context,
        lastError,
      );
    }

    return undefined;
  };

  return acquireLock();
}

export interface MetricsLog {
  logType: string;
  daprMetrics?: DaprMetrics;
  osMetrics?: OsMetrics;
  processMetrics: ProcessMetrics;
}

export interface DaprMetrics {
  goMemstatsHeapAlloc: number;
  residentMemory: number;
}

export interface OsMetrics {
  cpuLoadAvg1?: number;
  cpuLoadAvg5?: number;
  cpuLoadAvg15?: number;
  freeMemory: number;
  totalMemory: number;
}

export interface ProcessMetrics {
  rss: number;
  heapTotal: number;
  heapUsed: number;
  external: number;
  arrayBuffers: number;
}

import * as os from 'node:os';
import { JobsLogContext } from '@mesx/common-lib';
import axios from 'axios';
import {
  OsMetrics,
  DaprMetrics,
  MetricsLog,
  ProcessMetrics,
} from './log-metrics-type';
import { AppLogger } from '@/common/logger/app-logger';

/**
 * Retrieve container metrics
 * @returns os metrics
 */
function getOSMetrics(): OsMetrics {
  const cpuLoadAvg = os.loadavg();
  return {
    cpuLoadAvg1: cpuLoadAvg.shift(),
    cpuLoadAvg5: cpuLoadAvg.shift(),
    cpuLoadAvg15: cpuLoadAvg.shift(),
    freeMemory: os.freemem() / (1024 * 1024),
    totalMemory: os.totalmem() / (1024 * 1024),
  };
}

/**
 * Retrieve process metrics
 * @returns process metrics
 */
function getProcessMetrics(): ProcessMetrics {
  const processMetrics = process.memoryUsage();
  processMetrics.arrayBuffers /= 1024 * 1024;
  processMetrics.external /= 1024 * 1024;
  processMetrics.heapTotal /= 1024 * 1024;
  processMetrics.heapUsed /= 1024 * 1024;
  processMetrics.rss /= 1024 * 1024;
  return processMetrics;
}

/**
 * Function to extract CPU and memory usage from Dapr metrics
 * @param metrics metrics http results
 * @returns metrics
 */
function extractDaprSideCarMetrics(metrics: string): DaprMetrics {
  const residentMemoryRegex = /process_resident_memory_bytes\s+([\d+.e]+)/; // Handle scientific notation
  const goMemstatsHeapAllocRegex = /go_memstats_heap_alloc_bytes\s+([\d+.e]+)/; // Handle scientific notation

  const residentMemoryMatch = residentMemoryRegex.exec(metrics);
  const goMemstatsHeapAllocMatch = goMemstatsHeapAllocRegex.exec(metrics);

  const residentMemory = residentMemoryMatch
    ? Number.parseFloat(residentMemoryMatch[1]) / (1024 * 1024)
    : 0; // Convert bytes to MB
  const goMemstatsHeapAlloc = goMemstatsHeapAllocMatch
    ? Number.parseFloat(goMemstatsHeapAllocMatch[1]) / (1024 * 1024)
    : 0; // Convert bytes to MB

  return {
    goMemstatsHeapAlloc: Number.parseFloat(goMemstatsHeapAlloc.toFixed(2)), // In MB
    residentMemory: Number.parseFloat(residentMemory.toFixed(2)), // In MB
  };
}

export class LogMetricsWorker {
  private readonly metricsUrl: string;

  private readonly logger: AppLogger;

  private workerThreadId: number | undefined = undefined;

  public constructor(
    logger: AppLogger,
    protocol = 'http',
    host = 'localhost',
    port = 9090,
  ) {
    this.logger = logger;
    this.metricsUrl = `${protocol}://${host}:${port}/metrics`;
  }

  /**
   * Get dapr metrics
   * @returns dapr metrics
   */
  private async getDaprSideCarMetrics(): Promise<DaprMetrics | undefined> {
    const context: JobsLogContext = {
      method: 'getDaprSideCarMetrics',
      service: 'LogMetricsWorker',
    };
    try {
      const response = await axios.get(this.metricsUrl);
      const metrics = response.data;
      return extractDaprSideCarMetrics(metrics);
    } catch (error) {
      this.logger.error(
        `Error fetching Dapr metrics ${this.metricsUrl}:`,
        context,
        error.message ?? error.stack,
      );
    }
    return undefined;
  }

  /**
   * Retrieve dapr and os metrics
   * then log the metrics
   */
  private async logMetrics(): Promise<void> {
    const context: JobsLogContext = {
      method: 'logMetrics',
      service: 'LogMetricsWorker',
    };
    const metricsLog: MetricsLog = {
      daprMetrics: await this.getDaprSideCarMetrics(),
      logType: 'Metrics',
      osMetrics: getOSMetrics(),
      processMetrics: getProcessMetrics(),
    };
    this.logger.log(JSON.stringify(metricsLog), context);
  }

  /**
   * Function to start the worker
   * that performs regular getMetrics calls
   * @param interval interval in ms
   */
  public startWorker(interval = 1000): void {
    if (this.workerThreadId) {
      return;
    }

    this.workerThreadId = setInterval(
      () => this.logMetrics(),
      interval,
    ) as unknown as number;
  }

  /**
   * Function to stop the worker
   */
  public stopWorker(): void {
    if (!this.workerThreadId) return;
    clearInterval(this.workerThreadId);
    this.workerThreadId = undefined;
  }
}

import { JobsLogContext, RedisClientInstance } from '@mesx/common-lib';
import { acquireLockWithTimeout } from '../locks/acquire-lock';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';
import { QueueMessage } from '@/interface/queue-message';

/**
 * Append and save to Redis queue
 * @param logger Application logger
 * @param queueName Queue name
 * @param message Message to append
 * @param serviceMutexes Mutexes for the services
 * @param redisClient Redis client instance
 */
export async function appendAndSaveToCacheQueue(
  logger: AppLogger,
  queueName: string,
  message: QueueMessage,
  serviceMutexes: MutexManagerService,
  redisClient: RedisClientInstance,
): Promise<void> {
  const context: JobsLogContext = {
    method: 'appendAndSaveToCacheQueue',
    object: queueName,
    plant: message.plant,
    service: 'appendAndSaveToCacheQueue',
  };
  const logOperationInfo = {
    name: 'appendAndSaveToCacheQueue',
    srcLocation: 'append-and-save-to-cache-queue.ts',
  };
  const logOperationDetail = {
    message,
    plantId: message.plant,
    queueName,
  };

  if (!message.plant) {
    return;
  }

  logOperationInfo.name = 'Acquire lock';
  const release = await execAndLog(
    logger,
    () =>
      acquireLockWithTimeout(
        logger,
        `${queueName}-${message.plant}`,
        serviceMutexes,
      ),
    logOperationInfo,
    logOperationDetail,
  );

  if (!release) {
    return;
  }

  try {
    const containerPrefix =
      process.env.STATE_PREFIX ?? 'leveling-board-state-mv';
    const redisQueueKey = `${containerPrefix}:${queueName}:${message.plant}`;

    if (redisClient) {
      const existingMessages = await redisClient.lRange(redisQueueKey, 0, -1);

      const messageExists = existingMessages.includes(JSON.stringify(message));

      if (!messageExists) {
        await redisClient.lPush(redisQueueKey, JSON.stringify(message));
      }
    }
  } catch (error) {
    logger.error(
      `Error appending and saving to Redis queue: ${error.message}`,
      context,
      error.stack,
    );
  } finally {
    if (release) {
      release();
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/common/logger/app-logger';
import { QueueMessage } from '@/interface/queue-message';

/**
 * Read from Redis cache queue.
 * @param logger Application logger
 * @param queueName Queue name
 * @param redisQueueState memory queue
 * @param plantId plant id
 * @returns Array of QueueMessage
 */
export async function readCacheQueue(
  logger: AppLogger,
  queueName: string,
  redisQueueState: { [queueName: string]: Array<QueueMessage> },
  plantId: number,
): Promise<Array<QueueMessage>> {
  const logOperationInfo = {
    name: 'readFromCacheQueue',
    srcLocation: 'read-from-cache-queue.ts',
  };
  const context: JobsLogContext = {
    method: 'readFromCacheQueue',
    object: queueName,
    plant: plantId,
    service: 'readFromCacheQueue',
  };

  try {
    // Fetch the Redis client
    logOperationInfo.name = 'Read queue';

    const queueMessages: Array<QueueMessage> =
      redisQueueState?.[queueName] || [];
    // Filter messages by plantId
    const filteredMessages = queueMessages.filter(
      (message) => String(message.plant) === String(plantId),
    );

    return filteredMessages;
  } catch (error) {
    logger.error(
      `Error reading from cache queue: ${error.message}`,
      context,
      error.stack,
    );
    return [];
  }
}

import { JobsLogContext, RedisClientInstance } from '@mesx/common-lib';
import { acquireLockWithTimeout } from '../locks/acquire-lock';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';
import { CacheTask } from '@/interface/cache-task';
import { QueueMessage } from '@/interface/queue-message';

/**
 * Reset queues with locks for Redis queues.
 * @param logger Application logger
 * @param serviceMutexes Mutexes for the queues
 * @param message Cache Task message
 * @param plantId plant Id
 * @param redisClient Redis client instance
 * @returns The modified cache task message
 */
export async function resetQueuesWithLocks(
  logger: AppLogger,
  serviceMutexes: MutexManagerService,
  message: CacheTask,
  plantId: number,
  redisClient: RedisClientInstance,
): Promise<CacheTask> {
  const context: JobsLogContext = {
    method: 'resetQueuesWithLocks',
    plant: plantId,
    service: 'resetQueuesWithLocks',
  };

  const logOperationInfo = {
    name: 'resetQueuesWithLocks',
    srcLocation: 'reset-queues-with-locks.ts',
  };

  const releases: Array<() => void> = [];
  const filteredQueueState: { [queueName: string]: Array<QueueMessage> } = {};

  try {
    // Acquire locks for queues to reset
    const queuesToReset = [
      'tpa',
      'outbound',
      'workcenter-updates',
      'launcher-kpi',
    ];

    // Iterate over each queue to reset
    for (const queueName of queuesToReset) {
      const lockKey = `${queueName}-${plantId}`;
      const release = await execAndLog(
        logger,
        () => acquireLockWithTimeout(logger, lockKey, serviceMutexes),
        { ...logOperationInfo, name: `Acquire lock for ${lockKey}` },
        { plantId, queueName },
      );

      if (!release) {
        throw new Error(`Failed to acquire lock for queue: ${lockKey}`);
      }
      releases.push(release);

      const containerPrefix =
        process.env.STATE_PREFIX ?? 'leveling-board-state-mv';
      const redisQueueKey = `${containerPrefix}:${queueName}:${plantId}`;

      const currentQueueState = await redisClient.lRange(redisQueueKey, 0, -1);
      if (currentQueueState.length > 0) {
        filteredQueueState[queueName] = currentQueueState.map(
          (item) => JSON.parse(item) as QueueMessage,
        );

        await redisClient.del(redisQueueKey);
      }
    }

    // Return the updated CacheTask with the cached queue state
    return { ...message, redisQueueState: filteredQueueState };
  } catch (error) {
    logger.error(
      `Error resetting queues with locks: ${error.message}`,
      context,
      error.stack,
    );
    throw error;
  } finally {
    // Release all locks after processing
    while (releases.length > 0) {
      const release = releases.pop();
      if (release) {
        release();
      }
    }
  }
}

import { IsInt, IsOptional, IsBoolean, IsNumber } from 'class-validator';

export class ExponentialBackoffRetryDto {
  @IsOptional()
  @IsInt()
  @IsNumber()
  public retries?: number = 5; // Default value of 5 retries

  @IsOptional()
  @IsInt()
  @IsNumber()
  public baseDelayMs?: number = 1000; // Default value of 1000 ms

  @IsOptional()
  @IsBoolean()
  public jitter?: boolean = true; // Default value for jitter is true

  @IsOptional()
  @IsInt()
  @IsNumber()
  public attempt?: number = 1; // Default value of 1 attempt

  @IsOptional()
  @IsInt()
  @IsNumber()
  public maxBackoff?: number = 32; // Default value for max backoff is 32
}

import { randomInt } from 'node:crypto';
import { ExponentialBackoffRetryDto } from './dtos/exponential-backoff-retry.dto'; // Correct path to DTO
import { exponentialBackoffRetry } from './exponential-backoff-retry'; // Correct path to the function
