// Mock the AppLogger
const mockLogger = {
  error: jest.fn(),
  warn: jest.fn(),
} as unknown as AppLogger;
const context = {
  method: 'exponentialBackoffRetryTest',
  service: 'retryService',
};

// Mock randomInt
jest.mock('node:crypto', () => ({
  randomInt: jest.fn(),
}));

// Test the calculateExponentialBackoffDelay function
describe('calculateExponentialBackoffDelay', () => {
  const { calculateExponentialBackoffDelay } = jest.requireActual(
    './exponential-backoff-retry',
  );

  it('should calculate the correct delay with jitter', () => {
    const attempt = 3;
    const maxBackoff = 3;
    const mockJitter = 500; // Mock jitter value

    (randomInt as jest.Mock).mockReturnValue(mockJitter); // Mock randomInt

    const delay = calculateExponentialBackoffDelay(attempt, maxBackoff);

    const expectedDelay = Math.min(
      2 ** attempt * 1000 + mockJitter,
      maxBackoff * 1000,
    );
    expect(delay).toBe(expectedDelay);
    expect(delay).toBeLessThanOrEqual(maxBackoff * 1000);
  });

  it('should cap the delay at maxBackoff', () => {
    const attempt = 10;
    const maxBackoff = 3;
    (randomInt as jest.Mock).mockReturnValue(500); // Mock jitter value

    const delay = calculateExponentialBackoffDelay(attempt, maxBackoff);

    expect(delay).toEqual(maxBackoff * 1000); // Capped at maxBackoff
  });
});

// Test the exponentialBackoffRetry function
describe('exponentialBackoffRetry', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should retry the operation and succeed', async () => {
    const mockOperation = jest
      .fn()
      .mockRejectedValueOnce(
        Object.assign(new Error('Some retryable error'), {
          name: 'AbortError',
        }),
      )
      .mockResolvedValue('Success');

    // Create an instance of ExponentialBackoffRetryDto
    const retryOptions = new ExponentialBackoffRetryDto();
    retryOptions.retries = 2; // Reduced retries
    retryOptions.baseDelayMs = 10; // Reduced baseDelayMs
    retryOptions.jitter = true; // Enable jitter
    retryOptions.maxBackoff = 1; // Reduced maxBackoff

    const result = await exponentialBackoffRetry(
      mockLogger,
      context,
      mockOperation,
      retryOptions, // Pass the DTO object here
    );

    expect(result).toBe('Success');
    expect(mockOperation).toHaveBeenCalledTimes(2); // Initial + 1 retry
  });

  it('should throw after exceeding retries', async () => {
    const mockOperation = jest.fn().mockRejectedValue(
      Object.assign(new Error('Persistent error'), {
        code: 429,
      }),
    );

    // Create an instance of ExponentialBackoffRetryDto
    const retryOptions = new ExponentialBackoffRetryDto();
    retryOptions.retries = 2; // Reduced retries
    retryOptions.baseDelayMs = 10; // Reduced baseDelayMs
    retryOptions.jitter = true; // Enable jitter
    retryOptions.maxBackoff = 1; // Reduced maxBackoff

    await expect(
      exponentialBackoffRetry(
        mockLogger,
        context,
        mockOperation,
        retryOptions, // Pass the DTO object here
      ),
    ).rejects.toThrow('Persistent error');

    expect(mockOperation).toHaveBeenCalledTimes(2); // Ensure retries were exhausted
    expect(mockLogger.error).toHaveBeenCalledWith(
      expect.stringContaining('Operation failed after 2 retries'),
      expect.objectContaining({
        method: 'exponentialBackoffRetryTest',
        service: 'retryService',
      }),
    );
  });

  it('should not retry on non-retryable error', async () => {
    const mockOperation = jest
      .fn()
      .mockRejectedValue(
        Object.assign(new Error('Non-retryable error'), { name: 'TypeError' }),
      );

    // Create an instance of ExponentialBackoffRetryDto
    const retryOptions = new ExponentialBackoffRetryDto();
    retryOptions.retries = 3; // More retries
    retryOptions.baseDelayMs = 10; // Delay of 10ms
    retryOptions.maxBackoff = 3; // Max backoff of 3
    retryOptions.jitter = true; // Enable jitter

    await expect(
      exponentialBackoffRetry(mockLogger, context, mockOperation, retryOptions), // Pass the DTO object here
    ).rejects.toThrow('Non-retryable error');

    expect(mockOperation).toHaveBeenCalledTimes(1); // No retry
    expect(mockLogger.error).toHaveBeenCalledWith(
      expect.stringContaining('Non-retryable error encountered'),
      expect.objectContaining({
        method: 'exponentialBackoffRetryTest',
        service: 'retryService',
      }),
    );
  });
});

import { randomInt } from 'node:crypto';
import { JobsLogContext } from '@mesx/common-lib';
import { ExponentialBackoffRetryDto } from './dtos/exponential-backoff-retry.dto'; // Path to your DTO
import { AppLogger } from '@/common/logger/app-logger';

/**
 * Calculates the delay for the next retry attempt using exponential backoff with a random jitter.
 * @param attempt - The current attempt number.
 * @param maxBackoff - The maximum backoff time in seconds.
 * @returns The calculated delay in milliseconds.
 */
export function calculateExponentialBackoffDelay(
  attempt: number,
  maxBackoff: number,
): number {
  const randomNumberMilliseconds = randomInt(0, 1000); // Random number between 0 and 1000
  const exponentialDelay = 2 ** attempt; // 2^n
  return Math.min(
    exponentialDelay * 1000 + randomNumberMilliseconds,
    maxBackoff * 1000,
  ); // Convert seconds to milliseconds
}

/**
 * Retries a given operation a specified number of times with an exponential backoff delay between attempts.
 * @template T The type of the result returned by the operation.
 * @param logger - Logger instance for logging.
 * @param context - Job Log Context.
 * @param operation - The operation to retry.
 * @param options - Options object containing the parameters for the backoff retry, such as retries, baseDelayMs, jitter, attempt, and maxBackoff.
 * @returns A promise that resolves to the result of the operation.
 * @throws Will throw an error if the operation fails after the specified number of retries.
 */
export async function exponentialBackoffRetry<T>(
  logger: AppLogger,
  context: JobsLogContext,
  operation: () => Promise<T>,
  options: ExponentialBackoffRetryDto, // Using DTO here
): Promise<T> {
  const {
    retries = 5,
    baseDelayMs = 1000,
    jitter = true,
    attempt = 1,
    maxBackoff = 32,
  } = options; // Destructure the options DTO
  try {
    return await operation();
  } catch (error) {
    const isRetryableError =
      // If Redis returns a 5xx-like error (this would depend on the client you're using)
      error.code === 429 ||
      (error.code >= 500 && error.code < 600) ||
      error.message.includes('The client is closed') ||
      // Network or connection errors (Socket closed in case of redis infra redeploy)
      error.message.includes('Socket closed unexpectedly') ||
      // Network or connection errors (AbortError)
      error.name === 'AbortError' ||
      // Redis errors that indicate retryable conditions
      (error.name === 'ReplyError' &&
        (error.message.includes('TRYAGAIN') ||
          error.message.includes('READONLY')));
    if (!isRetryableError) {
      logger.error(
        `Non-retryable error encountered: ${(error as Error).message}`,
        context,
      );
      throw error; // Non-retryable error, rethrow
    }

    if (attempt >= retries) {
      logger.error(
        `Operation failed after ${retries} retries: ${(error as Error).message}`,
        context,
      );
      throw error;
    }
    // Calculate delay
    const delay = jitter
      ? calculateExponentialBackoffDelay(attempt, maxBackoff)
      : baseDelayMs * 2 ** (attempt - 1);
    await new Promise((resolve) => {
      setTimeout(resolve, delay);
    });
    return exponentialBackoffRetry(logger, context, operation, {
      ...options,
      attempt: attempt + 1,
    });
  }
}

