/**
 * Adds picking order information to an existing shop order.
 * @param order - The original shop order to update.
 * @param pickingOrder - The picking order with data to merge.
 * @returns The updated shop order with merged picking order data.
 */
export function addPickingOrderData(
  order: ShopOrder,
  pickingOrder: PickingOrderList,
): ShopOrder {
  const updatedOrder = { ...order };

  updatedOrder.alertId = pickingOrder.alertId;
  updatedOrder.alertLevel = pickingOrder.alertLevel;
  updatedOrder.alertStatus = pickingOrder.alertStatus;
  updatedOrder.alertCreationTime = pickingOrder.alertCreationTime;
  updatedOrder.alertCreated = pickingOrder.alertCreated;
  updatedOrder.customer = pickingOrder.customer;
  updatedOrder.shopOrder = pickingOrder.pickingOrderId;
  updatedOrder.plant = pickingOrder.plant;
  updatedOrder.material = pickingOrder.material;
  updatedOrder.newPromiseTime = pickingOrder.newPromiseTime;
  updatedOrder.wcCode = pickingOrder.workcenter;
  updatedOrder.customStatus = pickingOrder.customStatus;
  updatedOrder.sourceLocation = pickingOrder.sourceLocation;
  updatedOrder.destinationLocation = pickingOrder.destinationLocation;
  updatedOrder.erpDelNo = pickingOrder.outbound;
  updatedOrder.plannedStartDate = pickingOrder.plannedStartDate;
  updatedOrder.pickingTime = pickingOrder.plannedStartDate;
  updatedOrder.reschedulerWkHistories = pickingOrder.reschedulerWkHistories;
  updatedOrder.status = pickingOrder.status || '';
  updatedOrder.launcherWaitingTime =
    pickingOrder.launcherWaitingTime?.value || '';

  return updatedOrder;
}

/**
 * Adds a TTL (time-to-live) property to the shop order if its status is '504' or '503'.
 * The TTL is set so the document expires 7 days after the planned start date.
 * @param updatedOrder - The shop order to update.
 * @returns The updated shop order with the TTL property, or unchanged if not applicable.
 */
export function addTtlToOrder(updatedOrder: ShopOrder): ShopOrder {
  let ttl = 0;
  if (updatedOrder.status === '503') {
    if (updatedOrder.plannedStartDate) {
      const plannedDate = new Date(updatedOrder.plannedStartDate);
      const now = new Date();

      // Set TTL so the doc expires 7 days after plannedStartDate
      const expiryDate = new Date(
        plannedDate.getTime() + 7 * 24 * 60 * 60 * 1000,
      );
      ttl = Math.floor((expiryDate.getTime() - now.getTime()) / 1000);
    }

    return {
      ...updatedOrder,
      ttl,
    };
  }
  return updatedOrder;
}

import { Mutex } from 'async-mutex';

export const pendingMessageStats = {
  count: 0,
};

export const pendingMessageCountMutex = new Mutex();

/**
 * Increment the general counter
 */
export function incrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count += 1;
  });
}

/**
 * Decrement the general counter
 */
export function decrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count -= 1;
  });
}

/**
 * Return count property from pendingMessageStats
 * @returns count property
 */
export function getPendingMessagesCount(): number {
  return pendingMessageStats.count;
}

import { JobsLogContext } from '@mesx/common-lib';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { PickingOrderList } from '@/interface/picking-order-list';
import { ShopOrder } from '@/interface/shop-order';
import { UpdateCacheOrders } from '@/update-cache/update-cache-orders';

// Create a function to process cache updates sequentially for a given order
/**
 *
 * @param pickingOrder - The picking order to be processed.
 * @param updateCacheServices - Update cache services
 * @param updateCacheServices.updateCacheOrders - A function that updates the cache for orders.
 *     This function should accept a PickingOrderRequestDto object and return a promise
 *     that resolves to a ShopOrder.
 * @param logger - logger function
 * @param shopOrderResultsBuffer - the array that contain the result
 * @returns shopOrder results
 */
export async function createUpdateOrder(
  pickingOrder: PickingOrderList,
  updateCacheServices: {
    updateCacheOrders: UpdateCacheOrders;
  },
  logger: AppLogger,
  shopOrderResultsBuffer: Array<ShopOrder>,
): Promise<void> {
  try {
    const { updateCacheOrders } = updateCacheServices;
    const logOperationInfo = {
      name: '',
      srcLocation: 'updateCacheSequentially - processItem',
    };
    // Step 1: Update Cache for Order
    logOperationInfo.name = 'updateCacheForOrder';
    const updatedShopOrder = (await execAndLog(
      logger,
      () => updateCacheOrders.updateCacheForOrder(pickingOrder),
      logOperationInfo,
      { item: pickingOrder },
    )) as ShopOrder;

    if (!updatedShopOrder) {
      return; // Skip further processing if order cache update fails
    }
    // Add the updated ShopOrder to the results buffer
    shopOrderResultsBuffer.push(updatedShopOrder);
  } catch (error) {
    const context: JobsLogContext = {
      method: 'createUpdateOrder',
      object: pickingOrder.pickingOrderId,
      plant: pickingOrder.plant,
      service: 'createUpdateOrder',
    };
    logger.error(
      `Failed to process cache updates for order: ${pickingOrder.pickingOrderId}`,
      context,
      error,
    );
  }
}

import { ConfigService } from '@nestjs/config';
import { DaprClient } from 'dapr-client';
import { MasterApi } from '@/api/master-api';
