import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { AppLogger } from '@/common/logger/app-logger';
import { RedisConfigService } from '@/config/redis/redis-store.service';
import { LastUpdateTaskRecord } from '@/interface/last-update-task-record';

@Injectable()
export class LastUpdateTaskRecordService {
  public constructor(
    private readonly daprClient: DaprClient,
    private readonly redisConfigService: RedisConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public async readLastUpdateTaskRecord(
    plantKey: string,
  ): Promise<LastUpdateTaskRecord> {
    const { redisUpdateAmr } = this.redisConfigService;
    const context: JobsLogContext = {
      method: 'readLastUpdateTaskRecord',
      plant: Number(plantKey),
      service: 'LastUpdateTaskRecordService',
    };
    try {
      const result: unknown = await this.daprClient.state.get(
        redisUpdateAmr,
        plantKey,
      );
      let lastUpdateResult: LastUpdateTaskRecord = {
        lastUpdateTime: new Date(),
        updatedOn: new Date(),
      };
      if (result !== undefined && result !== '') {
        // Attempt to parse the result if it's a string
        lastUpdateResult =
          typeof result === 'string'
            ? (JSON.parse(result) as LastUpdateTaskRecord)
            : (result as LastUpdateTaskRecord);
      }

      lastUpdateResult.lastUpdateTime = new Date(
        lastUpdateResult.lastUpdateTime,
      );

      lastUpdateResult.updatedOn = new Date(lastUpdateResult.updatedOn);
      return lastUpdateResult;
    } catch (error) {
      this.customLogger.error(
        `Plant ${plantKey} - Error reading from Redis: ${error.message}`,
        context,
        error.stack,
      );
      throw error; // Rethrow the error after logging
    }
  }

  public async writeLastUpdateTaskRecord(
    plantKey: string,
    lastUpdateTaskRecord: LastUpdateTaskRecord,
  ): Promise<void> {
    const { redisUpdateAmr } = this.redisConfigService;
    const context: JobsLogContext = {
      method: 'writeLastUpdateTaskRecord',
      plant: Number(plantKey),
      service: 'LastUpdateTaskRecordService',
    };
    try {
      const value = { ...lastUpdateTaskRecord };
      value.updatedOn = new Date();
      await this.daprClient.state.save(redisUpdateAmr, [
        { key: plantKey, value },
      ]);
    } catch (error) {
      this.customLogger.error(
        `Plant ${plantKey} writeRecords - Error writing to Redis ${plantKey} ${error.message}`,
        context,
        error.stack,
      );
      throw error; // Rethrow the error after loggingObject:
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { MasterApi } from 'src/api/master-api';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { ShopOrder } from '@/interface/shop-order';

@Injectable()
export class UpdateCacheMaster {
  public constructor(
    private readonly masterApi: MasterApi,
    private readonly customLogger: AppLogger,
  ) {}

  public async updateCacheMaster(
    plant: string,
    shopOrders: Array<ShopOrder>,
  ): Promise<Array<ShopOrder>> {
    const logOperationInfo = {
      name: '',
      srcLocation: 'updateCacheMaster',
    };
    const context: JobsLogContext = {
      method: 'updateCacheMaster',
      plant: Number(plant),
      service: 'updateCacheMaster',
    };
    const oldShopOrders = shopOrders;
    try {
      // Check if pickingOrderId exists
      const locations = [
        ...new Set(
          shopOrders.flatMap((item) => [
            item.sourceLocation,
            item.destinationLocation,
          ]),
        ),
      ];

      const locationtypes = await execAndLog(
        this.customLogger,
        () =>
          this.masterApi.fetchStorageLocationListTypeByPlantAndId(
            Number(plant),
            locations,
          ),
        logOperationInfo,
        { receivedData: shopOrders },
      );
      if (locationtypes) {
        for (const shopOrder of shopOrders) {
          shopOrder.sourceType = locationtypes[shopOrder.sourceLocation] ?? '';
          shopOrder.destinationType =
            locationtypes[shopOrder.destinationLocation] ?? '';
        }
      }
      return shopOrders; // Return undefined if material data is not fetched successfully
    } catch (error) {
      this.customLogger.error(
        `Plant ${plant} - Error updateCacheMaster: ${error.message}`,
        context,
        error.stack,
      );
      return oldShopOrders; // Return undefined in case of an error
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OrderApi } from 'src/api/order-api';
import { AppLogger } from '@/common/logger/app-logger';
import { MaterialRequestDto } from '@/dtos/material-request.dto';
import { PickingOrderList } from '@/interface/picking-order-list';

@Injectable()
export class UpdateCacheOrders {
  public constructor(
    private readonly orderapi: OrderApi,
    private readonly customLogger: AppLogger,
  ) {}

  public async updateCacheForOrder(
    receivedData: PickingOrderList,
  ): Promise<object | undefined> {
    const context: JobsLogContext = {
      method: 'updateCacheForOrder',
      plant: receivedData.plant,
      service: 'UpdateCacheOrders',
    };
    try {
      // Extract data from pickingData
      const {
        alertId,
        alertLevel,
        alertStatus,
        alertCreationTime,
        alertCreated,
        containsHoldChildren,
        customer,
        endProductionTime,
        pickingOrderId,
        plant,
        material,
        newPromiseTime,
        workcenter,
        customStatus,
        sourceLocation,
        destinationLocation,
        outbound,
        plannedStartDate,
        reschedulerWkHistories,
        status,
        tpaNumber,
        launcherWaitingTime,
        maxLauncherWaitingTime,
        minLauncherWaitingTime,
      } = receivedData;

      // Fetch sebango from material-dtl in order domain
      const materialRequest = new MaterialRequestDto();
      materialRequest.plant = receivedData.plant;
      materialRequest.materialId = receivedData.material; // Using the receivedData instead of fetching from Redis

      const materialResponse =
        await this.orderapi.fetchSebango(materialRequest);
      const sebango = materialResponse?.sebango ?? '';

      let ttl: number | undefined;

      if (plannedStartDate && status === '503') {
        const SEVEN_DAYS_IN_SECONDS = 7 * 24 * 60 * 60;
        const plannedDate = new Date(plannedStartDate);
        const now = new Date();
        // Set TTL so the doc expires 7 days after plannedStartDate
        const expiryDate = new Date(
          plannedDate.getTime() + 7 * 24 * 60 * 60 * 1000,
        );
        ttl = Math.floor((expiryDate.getTime() - now.getTime()) / 1000);
        // If expiry is in the past, set ttl to 0 (expire immediately)
        ttl = ttl < 0 ? 0 : Math.min(ttl, SEVEN_DAYS_IN_SECONDS);
      }

      // Build the updated pickingOrderData
      const pickingOrderData = {
        advancePickingDuration: '',
        alertCreated,
        alertCreationTime,
        alertId,
        alertLevel,
        alertStatus,
        closeable: false,
        color: '',
        containsHoldChildren,
        customStatus,
        customer,
        customerDesc: '',
        destinationLocation,
        destinationType: '',
        endProductionTime,
        erpDelNo: outbound,
        flow: '',
        id: pickingOrderId,
        launcherWaitingTime: launcherWaitingTime?.value?.toString() ?? '',
        maxLauncherWaitingTime: maxLauncherWaitingTime?.toString() ?? '',
        minLauncherWaitingTime: minLauncherWaitingTime?.toString() ?? '',
        lockAction: '',
        lockDateTime: '',
        lockList: [],
        material,
        newPromiseTime,
        pickingTime: plannedStartDate,
        plannedStartDate,
        plant,
        reschedulerWkHistories,
        sebango,
        shopOrder: pickingOrderId,
        sourceLocation,
        sourceType: '',
        status,
        tpaBeginPreparation: '',
        tpaCode: '',
        tpaEndPreparation: '',
        tpaNumber,
        truck: '',
        truckDepartureTime: '',
        ttl,
        uapId: '',
        wcCode: workcenter,
        wcDesc: '',
      };

      // Validate the consistency of received data with API data
      if (!pickingOrderId.includes(receivedData.pickingOrderId)) {
        return undefined;
      }
      if (Number(plant) !== Number(receivedData.plant)) {
        return undefined;
      }

      const updatedData = {
        ...pickingOrderData,
      };

      // Handle lockAction reset based on certain conditions
      if (
        pickingOrderData.lockAction === 'NOT_AVAILABLE' ||
        pickingOrderData.lockAction === 'RESCH' ||
        receivedData.plannedStartDate !== plannedStartDate
      ) {
        updatedData.lockAction = '';
        updatedData.lockDateTime = '';
        updatedData.lockList = [];
      }

      // Return the updated pickingOrderData
      return updatedData;
    } catch (error) {
      this.customLogger.error(
        `Plant ${receivedData.plant} - Error updateCacheForOrder: ${error.message}`,
        context,
        error.stack,
      );
      return undefined; // Return undefined in case of an error
    }
  }
}

