import { Injectable } from '@nestjs/common';
import { BufferWkResponse } from '../interface/buffer-wk-list';
import { UpdateCacheMaster } from './update-cache-master';
import { UpdateCacheOrders } from './update-cache-orders';
import { UpdateCacheHYR } from './update-cache-plant-hierarchy';
import { UpdateCacheShipment } from './update-cache-shipment';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { CosmosDatabaseService } from '@/cosmos-db/cosmos.database.service';
import { PickingOrderRequestDto } from '@/dtos/picking-order-request.dto';
import { PickingResponse } from '@/dtos/picking-response.dto';
import { createUpdateOrder } from '@/helpers/updates/create-update-order';
import { updateOrderData } from '@/helpers/updates/update-order-data';
import { OrderUpdate } from '@/interface/order-update';
import { PickingOrderList, PickingOrder } from '@/interface/picking-order-list';
import { ShopOrder } from '@/interface/shop-order';

@Injectable()
export class UpdateCacheSequentially {
  public constructor(
    private readonly updateCacheOrders: UpdateCacheOrders,
    private readonly updateCacheMasters: UpdateCacheMaster,
    private readonly updateCacheShipment: UpdateCacheShipment,
    private readonly updateCacheHYR: UpdateCacheHYR,
    private readonly cosmosDabaseService: CosmosDatabaseService,
    private readonly customLogger: AppLogger,
  ) {}

  private async processPickingOrder(
    pickingOrder: PickingOrder,
    shopOrderResultsBuffer: Array<ShopOrder>,
    shopOrderToBeDeleted: Array<PickingOrderRequestDto>,
  ): Promise<void> {
    const logOperationInfo = {
      name: '',
      srcLocation: 'updateCacheSequentially - processItem',
    };
    const context: JobsLogContext = {
      method: 'processPickingOrder',
      plant: pickingOrder.plant,
      service: 'UpdateCacheSequentially',
    };

    try {
      // Handle different statuses
      switch (pickingOrder.status) {
        case '501':
        case '502': {
          if (
            pickingOrder.customStatus !== undefined &&
            pickingOrder.customStatus !== ''
          ) {
            logOperationInfo.name = 'updateCacheContainer';
            // Continue processing with additional updates
            await execAndLog(
              this.customLogger,
              () =>
                createUpdateOrder(
                  pickingOrder,
                  {
                    updateCacheOrders: this.updateCacheOrders,
                  },
                  this.customLogger,
                  shopOrderResultsBuffer,
                ),
              logOperationInfo,
              { pickingOrder, shopOrderResultsBuffer },
            );
          }

          break;
        }
        case '503':
        case '504': {
          const plannedStartDate = pickingOrder.plannedStartDate
            ? new Date(pickingOrder.plannedStartDate)
            : undefined;

          const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

          // For DONE or CLOSED, delete if plannedStartDate is older than 7 days
          const shouldDelete =
            plannedStartDate && plannedStartDate < sevenDaysAgo;

          if (shouldDelete) {
            logOperationInfo.name = 'deleteFromCacheForOrder';
            shopOrderToBeDeleted.push(pickingOrder);
          } else {
            // We're gonna proceed with updating our pickingOrder
            logOperationInfo.name = 'updateCacheContainer';
            await execAndLog(
              this.customLogger,
              () =>
                createUpdateOrder(
                  pickingOrder,
                  {
                    updateCacheOrders: this.updateCacheOrders,
                  },
                  this.customLogger,
                  shopOrderResultsBuffer,
                ),
              logOperationInfo,
              { pickingOrder, shopOrderResultsBuffer },
            );
          }
          break;
        }
        default: {
          this.customLogger.error(
            `Invalid status code: ${pickingOrder.pickingOrderId}`,
            context,
          );
        }
      }
    } catch (error) {
      this.customLogger.error(
        `Plant ${pickingOrder.plant} - Failed to process order ${pickingOrder.pickingOrderId}: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  private async syncShopOrderResultsBuffer(
    logOperationInfo: { name: string; srcLocation: string },
    plantId: number,
    shopOrderResultsBuffer: Array<ShopOrder>,
  ): Promise<void> {
    const plant = plantId.toString();
    const updatedShopOrder = await execAndLog(
      this.customLogger,
      () =>
        updateOrderData(
          plant,
          shopOrderResultsBuffer,
          {
            updateCacheHYR: this.updateCacheHYR,
            updateCacheMasters: this.updateCacheMasters,
            updateCacheShipment: this.updateCacheShipment,
          },
          this.customLogger,
        ),
      logOperationInfo,
      { shopOrderResultsBuffer },
    );
    if (updatedShopOrder) {
      await execAndLog(
        this.customLogger,
        () => this.saveToCosmos(updatedShopOrder, plant),
        logOperationInfo,
        {
          plant,
          shopOrderResultsLength: shopOrderResultsBuffer.length,
        },
      );
      shopOrderResultsBuffer.splice(0, shopOrderResultsBuffer.length); // Clear the array after saving
    }
  }

  public async deleteShopOrderResultsBufferInCosmos(
    logOperationInfo: { name: string; srcLocation: string },
    plantId: number,
    shopOrderToBeDeleted:
      | Array<PickingOrderRequestDto>
      | Array<PickingResponse>,
  ): Promise<void> {
    const plant = plantId.toString();
    // Delete from cosmos DB
    await execAndLog(
      this.customLogger,
      () =>
        this.cosmosDabaseService.deleteShopOrders(plant, shopOrderToBeDeleted),
      logOperationInfo,
      { shopOrderToBeDeletedLength: shopOrderToBeDeleted.length },
    );
    shopOrderToBeDeleted.splice(0, shopOrderToBeDeleted.length);
  }

  public async updateCacheSequentially(
    pickingOrders: Array<PickingOrderList>,
  ): Promise<void> {
    const logOperationInfo = {
      name: '',
      srcLocation: 'updateCacheSequentially',
    };
    const shopOrderResultsBuffer: Array<ShopOrder> = []; // Array to hold results
    const shopOrderToBeDeleted: Array<PickingOrderRequestDto> = [];

    for (const pickingOrder of pickingOrders) {
      await this.processPickingOrder(
        pickingOrder,
        shopOrderResultsBuffer,
        shopOrderToBeDeleted,
      );
      // Check if we need to save to Cosmos
      if (shopOrderResultsBuffer.length >= 200) {
        logOperationInfo.name =
          'saveToCosmos shopOrderResultsBuffer.length >= 200';
        await this.syncShopOrderResultsBuffer(
          logOperationInfo,
          pickingOrder.plant,
          shopOrderResultsBuffer,
        );
      }

      if (shopOrderToBeDeleted.length >= 200) {
        logOperationInfo.name =
          'deleteCosmos shopOrderResultsBuffer.length >= 200';
        await this.deleteShopOrderResultsBufferInCosmos(
          logOperationInfo,
          pickingOrder.plant,
          shopOrderToBeDeleted,
        );
      }
    }

    // Check if there are results to save at the end of processing
    if (shopOrderResultsBuffer.length > 0) {
      logOperationInfo.name = 'saveToCosmos shopOrderResultsBuffer.length > 0';
      await this.syncShopOrderResultsBuffer(
        logOperationInfo,
        pickingOrders[0].plant,
        shopOrderResultsBuffer,
      );
    }

    if (shopOrderToBeDeleted.length > 0) {
      logOperationInfo.name = 'deleteToCosmos shopOrderToBeDeleted.length > 0';
      await this.deleteShopOrderResultsBufferInCosmos(
        logOperationInfo,
        pickingOrders[0].plant,
        shopOrderToBeDeleted,
      );
    }
  }

  private async saveToCosmos(
    shopOrderResults: Array<ShopOrder>,
    plantKey: string,
  ): Promise<void> {
    const logOperationInfo = {
      name: '',
      srcLocation: 'saveToCosmos',
    };
    const context: JobsLogContext = {
      method: 'saveToCosmos',
      plant: Number(plantKey),
      service: 'UpdateCacheSequentially',
    };
    try {
      logOperationInfo.name = 'Upsert in cosmos ';

      await execAndLog(
        this.customLogger,
        () => this.cosmosDabaseService.upsertBatchShopOrders(shopOrderResults),
        logOperationInfo,
        { plant: plantKey },
      );
    } catch (error) {
      this.customLogger.error(
        `plant ${plantKey} - Failed to save ShopOrders to Cosmos: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  public async saveToCosmosBuffer(
    shopOrderResults: Array<BufferWkResponse>,
    plantKey: string,
  ): Promise<void> {
    const logOperationInfo = {
      name: '',
      srcLocation: 'saveToCosmos',
    };
    const context: JobsLogContext = {
      method: 'saveToCosmos',
      plant: Number(plantKey),
      service: 'UpdateCacheSequentially',
    };
    try {
      logOperationInfo.name = 'Upsert in cosmos ';
      const filteredResults = shopOrderResults.filter(
        (order) =>
          order.bufferstatus !== 'SUCCESS' && order.bufferstatus !== 'ERROR',
      );
      await execAndLog(
        this.customLogger,
        () => this.cosmosDabaseService.upsertBatchWksBuffer(filteredResults),
        logOperationInfo,
        { plant: plantKey },
      );
    } catch (error) {
      this.customLogger.error(
        `plant ${plantKey} - Failed to save WkBuffer to Cosmos: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  public async replaceUpdateTocosmos(
    wksToBeUpdated: Record<string, OrderUpdate>,
    plantKey: number,
  ): Promise<void> {
    const logOperationInfo = {
      name: 'replace updated in cosmos',
      srcLocation: 'replaceUpdatesByWksByBatch',
    };
    const context: JobsLogContext = {
      method: 'replaceUpdatesByWksByBatch',
      plant: Number(plantKey),
      service: 'UpdateCacheSequentially',
    };
    try {
      await execAndLog(
        this.customLogger,
        () =>
          this.cosmosDabaseService.replaceUpdatesByWksByBatch(
            plantKey,
            wksToBeUpdated,
          ),
        logOperationInfo,
        { plant: plantKey, wksToBeUpdatedLength: wksToBeUpdated.length },
      );
    } catch (error) {
      this.customLogger.error(
        `plant ${plantKey} - Failed to replace update ShopOrders to Cosmos: ${error.message}`,
        context,
        error.stack,
      );
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { ShipmentApi } from 'src/api/shipment-api';
import { PlantHierarchyApi } from '@/api/plant-hierarchy-api';
import { AppLogger } from '@/common/logger/app-logger';
import { ShopOrder } from '@/interface/shop-order';

@Injectable()
export class UpdateCacheShipment {
  public constructor(
    private readonly shipmentApi: ShipmentApi,
    private readonly plantHierarchyApi: PlantHierarchyApi,
    private readonly customLogger: AppLogger,
  ) {}

  public async updateCacheShipment(
    plant: string,
    shopOrders: Array<ShopOrder>,
  ): Promise<Array<ShopOrder>> {
    const context: JobsLogContext = {
      method: 'updateCacheShipment',
      plant: Number(plant),
      service: 'UpdateCacheShipment',
    };
    const oldShopOrders = shopOrders;
    try {
      const outbounds = shopOrders
        .filter(
          (shoporder) =>
            shoporder.erpDelNo !== null || shoporder.erpDelNo === '',
        ) // Remove null customers
        .map((shoporder) => shoporder.erpDelNo as string); // Extract outbound list
      // Fetch TPA code using the shipment API
      const responseInvoker =
        await this.shipmentApi.getTpaAssignmentDetailsByPlantAndMultipleOutbounds(
          plant,
          outbounds,
        );
      const tpaData = responseInvoker;

      if (tpaData) {
        for (const shopOrder of shopOrders) {
          const tpaResult = tpaData[0]?.[shopOrder.erpDelNo];

          if (tpaResult) {
            shopOrder.tpaCode = tpaResult.tpaCode ?? '';
            shopOrder.tpaBeginPreparation = tpaResult.beginPrep || '';
            shopOrder.tpaEndPreparation = tpaResult.endPrep || '';
            shopOrder.truckDepartureTime = tpaResult.truckDeparture || '';
          } else {
            shopOrder.tpaCode = '';
            shopOrder.tpaBeginPreparation = '';
            shopOrder.tpaEndPreparation = '';
            shopOrder.tpaEndPreparation = '';
            shopOrder.truckDepartureTime = '';
          }
        }
      }
      const customerCodes = [
        ...new Set(
          shopOrders
            .map((shoporder) => shoporder?.customer)
            .filter(
              (customer): customer is string =>
                typeof customer === 'string' && customer.trim().length > 0,
            ),
        ),
      ];
      const sapServer = await this.plantHierarchyApi.getSapServerByPlant(plant);
      const customerDesc = await this.getCustomerDesc(
        customerCodes,
        sapServer.sapServer as string,
      );
      if (customerDesc) {
        for (const shopOrder of shopOrders) {
          shopOrder.customerDesc =
            shopOrder.customer && customerDesc[shopOrder.customer]
              ? customerDesc[shopOrder.customer]
              : '';
        }
      }
      return shopOrders; // Return an empty ShipCacheResponseDto if TPA code fetching was not successful
    } catch (error) {
      this.customLogger.error(
        `Plant ${plant} Error updateCacheShipment: ${error}`,
        context,
      );
      return oldShopOrders; // Return an empty ShipCacheResponseDto in case of an error
    }
  }

  public async getCustomerDesc(
    customerCodes: Array<string>,
    sapServer: string,
  ): Promise<Record<string, string> | undefined> {
    // Fetch customer description
    const responseInvoker = await this.shipmentApi.fetchCustomerByCodes(
      customerCodes,
      sapServer,
    );
    const data = responseInvoker;
    return data;
  }
}

