@Injectable()
export class UpdateCosmosStructure {
  private readonly processDatetimeto: string | undefined = undefined;

  private readonly scriptMode: string | undefined = undefined;

  private readonly slectedPlant: number | undefined = undefined;

  private readonly processDatetimeFrom: string | undefined = undefined;

  public constructor(
    private readonly cosmosDabaseService: CosmosDatabaseService,
    private readonly orderApi: OrderApi,
    private readonly plantHierarchyApi: PlantHierarchyApi,
    private readonly updateCosmosStructureJobConfigService: UpdateCosmosStructureJobConfigService,
    private readonly customLogger: AppLogger,
    private readonly shipmentApi: ShipmentApi,
    private readonly masterApi: MasterApi,
    private readonly updateCacheMasters: UpdateCacheMaster,
    private readonly updateCacheShipment: UpdateCacheShipment,
    private readonly updateCacheHYR: UpdateCacheHYR,
  ) {
    const plantValue = Number(updateCosmosStructureJobConfigService.plant);
    this.slectedPlant = Number.isFinite(plantValue) ? plantValue : undefined;
    this.scriptMode = updateCosmosStructureJobConfigService.mode;
    this.processDatetimeto =
      updateCosmosStructureJobConfigService.processDatetimeto === ''
        ? DateTime.now().toFormat('yyyy-MM-dd HH:mm:ss')
        : updateCosmosStructureJobConfigService.processDatetimeto;

    this.processDatetimeFrom =
      updateCosmosStructureJobConfigService.processDatetimeFrom === ''
        ? DateTime.now()
            .minus({
              hours: Number(
                updateCosmosStructureJobConfigService.processingPeriod,
              ),
            })
            .toFormat('yyyy-MM-dd HH:mm:ss')
        : updateCosmosStructureJobConfigService.processDatetimeFrom;

    this.plantHierarchyApi.setUseAxios(true);
    this.masterApi.setUseAxios(true);
    this.shipmentApi.setUseAxios(true);
    this.orderApi.setUseAxios(true);
  }

  public async updateCosmosStructure(): Promise<void> {
    await (this.scriptMode === 'FULL'
      ? this.fullSyncMode()
      : this.incrimentSyncMode());
  }

  private async fetchAllRelatedData(
    plant: number,
    materialIds: Array<string>,
  ): Promise<Record<string, string> | undefined> {
    return this.orderApi.getSebangoByMaterialDtlByIds({
      plant,
      materialIds,
    });
  }

  public async fullSyncMode(): Promise<void> {
    const context: JobsLogContext = {
      method: 'fullSyncMode',
      service: 'UpdateCosmosStructure',
    };
    try {
      const ordersCountByPlant =
        await this.orderApi.getShopOrdersCountByPlantList(this.slectedPlant);
      const chunkSize = Number(
        this.updateCosmosStructureJobConfigService.chunk,
      );
      if (ordersCountByPlant) {
        for (const [plant, ordersCount] of Object.entries(ordersCountByPlant)) {
          await this.deleteClosedShopOrders(Number(plant));

          const totalChunks = Math.ceil(ordersCount / chunkSize);

          for (let chunk = 0; chunk < totalChunks; chunk += 1) {
            const offset = chunk * chunkSize;
            await this.updateOrInsertShopOrders(
              Number(plant),
              chunkSize,
              offset,
            );
          }
        }
      }
    } catch (error) {
      this.customLogger.error(
        'Failed to process orders by plant',
        context,
        error,
      );
      throw error; // Re-throw if you want upstream code to know
    }
  }

  private async deleteClosedShopOrders(
    plant: number,
    processDatetimeFrom: string | undefined = undefined,
    processDatetimeTo: string | undefined = undefined,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'deleteClosedShopOrders',
      plant,
      service: 'UpdateCosmosStructure',
    };

    try {
      // Fetch closed shop order IDs from the API
      const closedShopOrderIds = await (this.scriptMode === 'INCREMENT' &&
      processDatetimeFrom &&
      processDatetimeTo
        ? this.orderApi.getClosedShopOrderIds(
            plant,
            new Date(processDatetimeFrom),
            new Date(processDatetimeTo),
          )
        : this.orderApi.getClosedShopOrderIds(plant));

      if (!closedShopOrderIds?.length) {
        return;
      }

      // Delegate to the Cosmos DB deletion method
      await this.cosmosDabaseService.deleteIfExistsByIds(
        closedShopOrderIds,
        plant,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to delete closed shop orders for plant ${plant}: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  private async updateOrInsertShopOrders(
    plant: number,
    chunkSize: number,
    offset: number,
  ): Promise<void> {
    // Fetch paginated shop orders
    const orders = await (this.scriptMode === 'FULL'
      ? this.orderApi.getPaginatedShopOrders(Number(plant), chunkSize, offset)
      : this.orderApi.fetchNotClosedOrdersByDate(
          plant,
          this.processDatetimeFrom,
          this.processDatetimeto,
        ));

    if (!orders) {
      return;
    }

    const resultBuffers = await (this.scriptMode === 'FULL'
      ? await this.orderApi.fetchPaginatedBufferOrdersByDate(
          plant,
          chunkSize,
          offset,
        )
      : this.orderApi.fetchOrdersByDateBuffer(plant, this.processDatetimeFrom));
    let newMaterialId = [];
    const { materialIds, pickingOrderIds } = extractUniqueValues(orders);
    if (resultBuffers) {
      const bufferMaterialIds = extractUniqueBufferValues(resultBuffers);
      newMaterialId = [...materialIds, ...bufferMaterialIds];
    }
    newMaterialId = materialIds;
    const etag = await this.cosmosDabaseService.getEtagsByIds(
      pickingOrderIds,
      plant,
    );
    const sebango = await this.fetchAllRelatedData(plant, newMaterialId);

    let updatedOrders: Array<ShopOrder> = [];
    let addOrders: Array<ShopOrder> = [];
    for (const order of Object.values(orders)) {
      let updatedOrder = createUpdatedOrder(order);
      updatedOrder = addTtlToOrder(updatedOrder);
      updatedOrder.sebango = sebango?.[order.material] ?? '';
      if (etag?.[updatedOrder.shopOrder]) {
        updatedOrder.etag = etag[updatedOrder.shopOrder];
        updatedOrders.push(updatedOrder);
      } else {
        addOrders.push(updatedOrder);
      }
    }
    if (resultBuffers) {
      for (const resultBuffer of resultBuffers) {
        const updatedOrder = createBufferOrders(resultBuffer);
        updatedOrder.sebango = sebango?.[updatedOrder.material] ?? '';
        addOrders.push(updatedOrder);
      }
    }
    if (updatedOrders.length > 0) {
      updatedOrders = await updateOrderData(
        String(plant),
        updatedOrders,
        {
          updateCacheHYR: this.updateCacheHYR,
          updateCacheMasters: this.updateCacheMasters,
          updateCacheShipment: this.updateCacheShipment,
        },
        this.customLogger,
      );
    }
    if (addOrders.length > 0) {
      addOrders = await updateOrderData(
        String(plant),
        addOrders,
        {
          updateCacheHYR: this.updateCacheHYR,
          updateCacheMasters: this.updateCacheMasters,
          updateCacheShipment: this.updateCacheShipment,
        },
        this.customLogger,
      );
    }
    await this.cosmosDabaseService.updateWithBatch(updatedOrders);
    await this.cosmosDabaseService.insertWithBatch(addOrders);
  }

  public async incrimentSyncMode(): Promise<void> {
    const context: JobsLogContext = {
      method: 'incrimentSyncMode',
      service: 'UpdateCosmosStructure',
    };
    try {
      const plantIds = this.slectedPlant
        ? [this.slectedPlant]
        : await this.plantHierarchyApi.getAllPlantIds();

      const chunkSize = Number(
        this.updateCosmosStructureJobConfigService.chunk,
      );
      if (plantIds) {
        for (const plantId of plantIds) {
          await this.deleteClosedShopOrders(
            plantId,
            this.processDatetimeFrom,
            this.processDatetimeto,
          );

          await this.updateOrInsertShopOrders(plantId, chunkSize, 0);
        }
      }
    } catch (error) {
      this.customLogger.error(
        'Failed to process orders by plant',
        context,
        error,
      );
      throw error; // Re-throw if you want upstream code to know
    }
  }
}

import { MaterialRequestDto } from '@/dtos/material-request.dto';
import { BufferWkResponse } from '@/interface/buffer-wk-list';

// Define the mock API types
interface MockOrderApi {
  fetchSebango: jest.Mock<
    Promise<{ sebango: string } | undefined>,
    [MaterialRequestDto]
  >;
}

interface MockMasterApi {
  fetchStorageLocationTypeByPlantAndId: jest.Mock<
    Promise<{ type: string } | undefined>,
    [string, string]
  >;
}

describe('Buffer order enrichment', () => {
  const mockOrderApi: MockOrderApi = {
    fetchSebango: jest.fn(),
  };

  const mockMasterApi: MockMasterApi = {
    fetchStorageLocationTypeByPlantAndId: jest.fn(),
  };

  const mockBuffer: Array<BufferWkResponse> = [
    {
      bufferstatus: 'active',
      customer: 'cstmr',
      destinationLocation: 'DST',
      endPickingDatetime: new Date('2023-01-01T10:00:00Z'),
      erpDelNo: 'OUT001',
      material: 'MAT01',
      neoStatus: 'open',
      plannedStartDate: '2023-01-01T17:00:00Z',
      plant: 1146,
      qtyToBuild: 10,
      qtytoBuild: 100,
      shopOrder: 'ORD1',
      sourceLocation: 'SRC',
      startPickingDatetime: new Date('2023-01-01T08:00:00Z'),
      tpaNumber: 'TPA001',
      wcCode: 'WC123',
    },
  ];

  // Function under test
  /**
   * Enriches a list of buffer work responses with additional information such as storage types and sebango.
   * @param resultBuffer - The array of buffer responses to enrich.
   * @param orderApi - The API used to fetch the sebango for a material.
   * @param masterApi - The API used to fetch the storage location type.
   * @returns A promise that resolves to an array of enriched buffer responses.
   */
  async function enrichBuffer(
    resultBuffer: Array<BufferWkResponse>,
    orderApi: MockOrderApi,
    masterApi: MockMasterApi,
  ): Promise<
    Array<
      BufferWkResponse & {
        destinationType: string;
        sebango: string;
        sourceType: string;
        sourceTable: string;
      }
    >
  > {
    return Promise.all(
      resultBuffer.map(async (item) => {
        const sourceTypeObject =
          await masterApi.fetchStorageLocationTypeByPlantAndId(
            String(item.plant),
            item.sourceLocation,
          );

        const destinationTypeObject =
          await masterApi.fetchStorageLocationTypeByPlantAndId(
            String(item.plant),
            item.destinationLocation,
          );

        const materialRequest = new MaterialRequestDto();
        materialRequest.plant = item.plant;
        materialRequest.materialId = item.material;

        const materialResponse = await orderApi.fetchSebango(materialRequest);
        const sebango = materialResponse?.sebango ?? '';

        return {
          ...item,
          destinationType: destinationTypeObject?.type ?? '',
          sebango,
          sourceTable: 'Buffer',
          sourceType: sourceTypeObject?.type ?? '',
        };
      }),
    );
  }

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should enrich a single buffer order with types and sebango', async () => {
    mockOrderApi.fetchSebango.mockResolvedValue({ sebango: 'SEB123' });
    mockMasterApi.fetchStorageLocationTypeByPlantAndId
      .mockResolvedValueOnce({ type: 'TYPE_SRC' })
      .mockResolvedValueOnce({ type: 'TYPE_DST' });

    const result = await enrichBuffer(mockBuffer, mockOrderApi, mockMasterApi);

    expect(result[0]).toEqual({
      ...mockBuffer[0],
      destinationType: 'TYPE_DST',
      sebango: 'SEB123',
      sourceTable: 'Buffer',
      sourceType: 'TYPE_SRC',
    });
  });

  it('should use empty string for missing sebango', async () => {
    mockOrderApi.fetchSebango.mockResolvedValue({ sebango: '' });
    mockMasterApi.fetchStorageLocationTypeByPlantAndId
      .mockResolvedValueOnce({ type: 'TYPE_SRC' })
      .mockResolvedValueOnce({ type: 'TYPE_DST' });

    const result = await enrichBuffer(mockBuffer, mockOrderApi, mockMasterApi);

    expect(result[0].sebango).toBe('');
  });

  it('should handle missing source/destination types', async () => {
    mockOrderApi.fetchSebango.mockResolvedValue({ sebango: 'SEB456' });
    mockMasterApi.fetchStorageLocationTypeByPlantAndId
      .mockResolvedValueOnce({ type: '' })
      .mockResolvedValueOnce({ type: '' });

    const result = await enrichBuffer(mockBuffer, mockOrderApi, mockMasterApi);

    expect(result[0].sourceType).toBe('');
    expect(result[0].destinationType).toBe('');
  });
});

