/**
 *
 * @param plant   plant id
 * @param outboundsList Array of outbound
 * @param orderApi Instance of OrderApi.
 * @param shipApi Instance of ShipmentApi.
 * @param updateCache Instance of updateCacheSequentially
 */
async function updatesWKLinkedToOutbound(
  plant: number,
  outboundsList: Array<string>,
  orderApi: OrderApi,
  shipApi: ShipmentApi,
  updateCache: UpdateCacheSequentially,
): Promise<void> {
  const wkIdsList = await orderApi.getOrderIdsByOutboundListAndPlant(
    plant,
    outboundsList,
  );
  const outboundsDetailsList =
    await shipApi.getTpaAssignmentDetailsByPlantAndMultipleOutbounds(
      String(plant),
      outboundsList,
    );
  const emptyUpdates = {
    tpaCode: '',
    tpaBeginPreparation: '',
    tpaEndPreparation: '',
    truckDepartureTime: '',
  };
  // Optimized functional version
  const result =
    outboundsDetailsList.length === 0
      ? Object.fromEntries(
          Object.values(wkIdsList ?? {}).flatMap((wkList) =>
            wkList.map((wk) => [wk, { updates: emptyUpdates }]),
          ),
        )
      : Object.fromEntries(
          outboundsDetailsList.flatMap((detailGroup) =>
            Object.entries(detailGroup).flatMap(([outbound, details]) =>
              (wkIdsList?.[outbound] ?? []).map((wk) => [
                wk,
                {
                  updates: {
                    tpaCode: details.tpaCode,
                    tpaBeginPreparation: details.beginPrep,
                    tpaEndPreparation: details.endPrep,
                    truckDepartureTime: details.truckDeparture,
                  },
                },
              ]),
            ),
          ),
        );
  await updateCache.replaceUpdateTocosmos(result, plant);
}
/**
 * Process WORKCENTER_UPDATES messages
 * Gets workcenter details from plant hierarchy API and order details from order API
 * and updates related work orders in cosmos
 * @param plant - Plant ID
 * @param workcentersList - Array of workcenter IDs to process
 * @param plantHierarchyApi - Instance of PlantHierarchyApi
 * @param orderApi - Instance of OrderApi
 * @param updateCache - Instance of UpdateCacheSequentially
 */
async function processWorkcenterUpdatesMessages(
  plant: number,
  workcentersList: Array<string>,
  plantHierarchyApi: PlantHierarchyApi,
  orderApi: OrderApi,
  updateCache: UpdateCacheSequentially,
): Promise<void> {
  const context = {
    method: 'processWorkcenterUpdatesMessages',
    service: 'WorkerService',
  };
  try {
    // Get workcenter details from plant hierarchy API

    const workcenterDetails = await plantHierarchyApi.getResourceDetailsByWcIds(
      Number(plant),
      workcentersList,
    );
    // Get all orders related to these workcenters
    const ordersData = await orderApi.getOrdersByWorkcenterList(
      plant,
      workcentersList,
    );
    // Transform workcenter and order data into cosmos update format
    const result = Object.fromEntries(
      (ordersData ?? [])
        .filter(
          (order) => order.workcenter && workcenterDetails?.[order.workcenter],
        )
        .map((order) => [
          order.pickingOrderId,
          {
            updates: {
              maxLauncherWaitingTime:
                workcenterDetails?.[order.workcenter]?.maxLauncherWaitingTime,
              minLauncherWaitingTime:
                workcenterDetails?.[order.workcenter]?.minLauncherWaitingTime,
            },
          } as OrderUpdate,
        ]),
    );
    if (Object.keys(result).length > 0) {
      await updateCache.replaceUpdateTocosmos(result, Number(plant));
    }
  } catch (error) {
    this.customLogger.error(
      `Failed to process workcenter updates: ${error.message}`,
      context,
      error.stack,
    );
  }
}

/**
 * Process LAUNCHER_KPI messages
 * Gets launcher KPI related work orders from order API and updates them in cosmos
 * @param plant - Plant ID
 * @param workcentersList - Array of workcenter IDs to fetch KPI values for
 * @param orderApi - Instance of OrderApi
 * @param updateCache - Instance of UpdateCacheSequentially
 */
async function processLauncherKpiMessages(
  plant: number,
  workcentersList: Array<string>,
  orderApi: OrderApi,
  updateCache: UpdateCacheSequentially,
): Promise<void> {
  const context = {
    method: 'processLauncherKpiMessages',
    service: 'WorkerService',
  };
  try {
    // Fetch KPI values for the workcenters
    const kpiResponse = await orderApi.getLauncherKpiByWorkcenterList(
      plant,
      workcentersList,
    );

    const validKpiWorkcenters = Array.isArray(kpiResponse)
      ? kpiResponse.filter(
          (kpiObject) => kpiObject.workcenter && kpiObject.value !== undefined,
        )
      : [];

    // Build a map of workcenter to KPI value
    const kpiMap = new Map<string, number>();
    for (const kpiObject of validKpiWorkcenters) {
      kpiMap.set(kpiObject.workcenter, kpiObject.value);
    }

    // Fetch all orders for all relevant workcenters in one go
    const allOrders = await Promise.all(
      [...kpiMap.keys()].map((workcenter) =>
        orderApi.getOrdersByWorkcenterList(plant, [workcenter]),
      ),
    );

    // Map workcenter to its orders
    const workcenterOrderMap = new Map<string, Array<any>>();
    for (const [index, workcenter] of [...kpiMap.keys()].entries()) {
      workcenterOrderMap.set(workcenter, allOrders[index] ?? []);
    }

    // Build updates object in WKS format
    const updates = Object.fromEntries(
      [...workcenterOrderMap.entries()].flatMap(([workcenter, ordersData]) => {
        const kpiValue = kpiMap.get(workcenter);
        if (kpiValue === undefined) {
          return [];
        }
        return (ordersData ?? [])
          .filter((order) => order.pickingOrderId)
          .map((order) => [
            order.pickingOrderId,
            {
              updates: {
                launcherWaitingTime: kpiValue,
              },
            },
          ]);
      }),
    );

    if (Object.keys(updates).length > 0) {
      await updateCache.replaceUpdateTocosmos(updates, Number(plant));
    }
  } catch (error) {
    this.customLogger.error(
      `Failed to load mappings: ${error.message}`,
      context,
      error.stack,
    );
  }
}
/**
 * Processes queue messages for outbound and TPA assignments.
 * @param logger - Logger instance for logging.
 * @param queueMessages - Array of outbound queue messages.
 * @param queueMessagesTpa - Array of TPA assignment queue messages.
 * @param queueMessagesWorcenter - Array of workcenter update messages.
 * @param queueMessagesLancherKpi - Array of launcher KPI messages.
 * @param orderApi - Instance of OrderApi.
 * @param shipmentApi - Instance of ShipmentApi.
 * @param plantHierarchyApi - Instance of PlantHierarchyApi.
 * @param updateCache  - Instance of updateCache
 */
async function processQueueMessages(
  logger: AppLogger,
  queueMessages: Array<QueueMessage>,
  queueMessagesTpa: Array<QueueMessage>,
  queueMessagesWorcenter: Array<WorkcenterUpdatesMessage>,
  queueMessagesLancherKpi: Array<LauncherKpiMessage>,
  orderApi: OrderApi,
  shipmentApi: ShipmentApi,
  plantHierarchyApi: PlantHierarchyApi,
  updateCache: UpdateCacheSequentially,
): Promise<void> {
  // Only log workcenter update flow
  const context = {
    method: 'processLauncherMessages',
    service: 'WorkerService',
  };
  if (queueMessages.length > 0) {
    const { plant } = queueMessages[0];
    const outboundsList: Array<string> = queueMessages.map(
      (queueMessage) => queueMessage.outbound ?? '',
    );
    await updatesWKLinkedToOutbound(
      plant,
      outboundsList,
      orderApi,
      shipmentApi,
      updateCache,
    );
  }
  if (queueMessagesTpa.length > 0) {
    const assignIds: Array<number> = queueMessagesTpa
      .map((q) =>
        q.tpaAssignement === undefined ? undefined : Number(q.tpaAssignement),
      )
      .filter((n): n is number => n !== undefined);

    const outboundList =
      await shipmentApi.getoutboundByPlantAndTpaAssignmentList(
        Number(queueMessagesTpa[0].plant),
        assignIds,
      );
    if (outboundList && outboundList.length > 0) {
      await updatesWKLinkedToOutbound(
        Number(queueMessagesTpa[0].plant),
        outboundList,
        orderApi,
        shipmentApi,
        updateCache,
      );
    }
  }
  if (queueMessagesWorcenter.length > 0) {
    const { plant } = queueMessagesWorcenter[0];
    const workcentersList: Array<string> = queueMessagesWorcenter.map(
      (message) => message.workcenterId ?? '',
    );
    await processWorkcenterUpdatesMessages(
      plant,
      workcentersList,
      plantHierarchyApi,
      orderApi,
      updateCache,
    );
  }
  if (queueMessagesLancherKpi.length > 0) {
    const { plant } = queueMessagesLancherKpi[0];
    const lancherKpisList: Array<string> = queueMessagesLancherKpi.map(
      (message) => message.workcenter ?? '',
    );
    await processLauncherKpiMessages(
      plant,
      lancherKpisList,
      orderApi,
      updateCache,
    );
  }
}

/**
 *@param data - data to process
 */
export async function processData(data: CacheTask): Promise<void> {
  const configService = new ConfigService();
  const appConfigIntialConfigService = new AppConfigInitialConfigService(
    configService,
  );
  const appConfig = new AppConfigService(appConfigIntialConfigService);
  const loggerConfigService = new LoggerConfigService(configService, appConfig);
  const customLogger = new AppLogger(loggerConfigService);
  const config = workerData?.config || {};
  await customLogger.init(config.logLevel);

  const context: JobsLogContext = {
    method: 'processData',
    plant: data.plant,
    service: 'WorkerService',
  };

  const startTime = Date.now();
  const logOperationInfo = {
    name: '',
    srcLocation: 'processData',
  };

  const logOperationDetail = {
    data,
  };

  try {
    // Worker threads run in isolation and cannot use NestJS DI
    // We create a single DaprClient instance for this worker thread

    const daprClient = new DaprClient();

    const daprConfigService = new DaprConfigService(
      configService,
      customLogger,
    );
    const orderApi = new OrderApi(daprClient, daprConfigService, customLogger);
    const shipmentApi = new ShipmentApi(
      daprClient,
      daprConfigService,
      customLogger,
    );
    const masterApi = new MasterApi(
      daprClient,
      daprConfigService,
      customLogger,
    );
    const plantHryApi = new PlantHierarchyApi(
      daprClient,
      daprConfigService,
      customLogger,
    );
    const eventhub = new EventhubService(configService, appConfig);
    const updateCache = await instantiateUpdateCacheSequentially(daprClient);

    const pickingData: Array<PickingOrderList> = [];

    const publishMessageService = new PublishMessageService(
      daprClient,
      eventhub,
      customLogger,
    );
    const eventhubService = new EventhubService(configService, appConfig);

    // Read the queue
    const queueMessages: Array<QueueMessage> = await readCacheQueue(
      customLogger,
      'outbound',
      data.redisQueueState ?? {},
      data.plant,
    );

    const queueMessagesWorcenter: Array<WorkcenterUpdatesMessage> =
      (await readCacheQueue(
        customLogger,
        'workcenter-updates',
        data.redisQueueState ?? {},
        data.plant,
      )) as Array<WorkcenterUpdatesMessage>;
    const queueMessagesLancherKpi: Array<LauncherKpiMessage> =
      (await readCacheQueue(
        customLogger,
        'launcher-kpi',
        data.redisQueueState ?? {},
        data.plant,
      )) as Array<LauncherKpiMessage>;

    const queueMessagesTpa: Array<QueueMessage> = await readCacheQueue(
      customLogger,
      'tpa',
      data.redisQueueState ?? {},
      data.plant,
    );
    if (
      queueMessages.length > 0 ||
      queueMessagesTpa.length > 0 ||
      queueMessagesWorcenter.length > 0 ||
      queueMessagesLancherKpi.length > 0
    ) {
      logOperationInfo.name = 'processQueueMessages';
      await processQueueMessages(
        customLogger,
        queueMessages,
        queueMessagesTpa,
        queueMessagesWorcenter,
        queueMessagesLancherKpi,
        orderApi,
        shipmentApi,
        plantHryApi,
        updateCache,
      );
    }

    // Fetch orders by date
    const updateTime = data.updateTime
      ? new Date(data.updateTime).getTime()
      : Date.now();
    const updateDurationInMs = Number(data.updateDuration) * 1000;
    const estimatedTime = updateTime - updateDurationInMs - 30 * 1000;
    const estimatedDate = new Date(estimatedTime);

    // Continue processing with additional updates
    logOperationInfo.name = 'fetchOrdersByDate';
    const responseInvoker: OrderResponse | undefined = await execAndLog(
      customLogger,
      () => orderApi.fetchOrdersByDate(data.plant, estimatedDate),
      logOperationInfo,
      logOperationDetail,
    );
    const result = responseInvoker?.result;
    const dateHeader =
      responseInvoker?.headers['date'] ?? new Date().toUTCString();
    const serverUTCDateTime = new Date(dateHeader);

    // Continue processing with additional updates
    logOperationInfo.name = 'fetchBufferOrdersByDate';
    const responseInvokerBuffer: BufferOrderResponse | undefined =
      await execAndLog(
        customLogger,
        () => orderApi.fetchBufferOrdersByDate(data.plant, estimatedDate),
        logOperationInfo,
        logOperationDetail,
      );

    let resultBuffer = responseInvokerBuffer?.result;
    // Const serverUTCDateTimeBuffer = responseInvoker?.headers['date'];
    if (
      (result?.length === 0 || !result) &&
      pickingData.length === 0 &&
      (resultBuffer?.length === 0 || !resultBuffer)
    ) {
      const publishTime = new Date(data.publishTime);
      const resultCache: CacheResult = {
        orchestratorPublishTime: data.publishTime,
        plant: data.plant,
        updateDuration: Math.floor((Date.now() - publishTime.getTime()) / 1000),
        updateTime: serverUTCDateTime
          ? new Date(serverUTCDateTime)
          : new Date(),
        uuid: data.uuid,
      };
      logOperationInfo.name = 'publishMessage';
      await execAndLog(
        customLogger,
        () =>
          publishMessageService.publishMessage(
            eventhubService.topicResults,
            resultCache,
          ),
        logOperationInfo,
        logOperationDetail,
      );
      return;
    }

    if (result) {
      pickingData.push(...result);
    }
    if (resultBuffer) {
      // Check for neoStatus === 'ERROR' and delete those items
      const wkToBeDeleted: Array<PickingResponse> = [];
      for (const item of resultBuffer) {
        if (item.neoStatus === 'ERROR') {
          wkToBeDeleted.push({
            plant: item.plant,
            pickingOrderId: item.shopOrder,
          });
        }
      }

      if (wkToBeDeleted.length > 0) {
        await updateCache.deleteShopOrderResultsBufferInCosmos(
          { name: 'deleteShopOrders', srcLocation: 'worker.ts' },
          data.plant,
          wkToBeDeleted,
        );
        // Filtrer le buffer local pour retirer les entrées supprimées
        resultBuffer = resultBuffer.filter(
          (item) => item.neoStatus !== 'ERROR',
        );
      }

      const allLocations = [
        ...new Set(
          resultBuffer.flatMap((item) => [
            item.sourceLocation,
            item.destinationLocation,
          ]),
        ),
      ];

      const locationTypeMap =
        await masterApi.fetchStorageLocationListTypeByPlantAndId(
          data.plant,
          allLocations,
        );

      const enrichedBuffer = await pMap(
        resultBuffer,
        async (item) => {
          const materialRequest = new MaterialRequestDto();
          materialRequest.plant = item.plant;
          materialRequest.materialId = item.material;

          const materialResponse = await orderApi.fetchSebango(materialRequest);

          const workcenterRequest = new WorkcenterRequestDTO();
          workcenterRequest.plant = item.plant;
          workcenterRequest.workcenter = item.wcCode;

          const workcenterResponse =
            await plantHryApi.fetchWorkcenterDetailsById(workcenterRequest);

          return {
            ...item,
            containsHoldChildren: false,
            customStatus: '',
            destinationType: locationTypeMap?.[item.destinationLocation] ?? '',
            sebango: materialResponse?.sebango ?? '',
            sourceTable: 'Buffer',
            sourceType: locationTypeMap?.[item.sourceLocation] ?? '',
            status: '',
            truck: '',
            wcDesc: workcenterResponse?.description ?? '',
          };
        },
        {
          concurrency: 1,
        },
      );

      await updateCache.saveToCosmosBuffer(enrichedBuffer, String(data.plant));
    }

    logOperationInfo.name = 'updateCacheSequentially';
    await execAndLog(
      customLogger,
      async () => {
        await updateCache.updateCacheSequentially(pickingData);
      },
      logOperationInfo,
      logOperationDetail,
    );

    const publishTime = new Date(data.publishTime);
    const resultCache: CacheResult = {
      orchestratorPublishTime: data.publishTime,
      plant: data.plant,
      updateDuration: Math.floor((Date.now() - publishTime.getTime()) / 1000),
      updateTime: serverUTCDateTime ? new Date(serverUTCDateTime) : new Date(),
      uuid: data.uuid,
    };

    logOperationInfo.name = 'publishMessage';
    await execAndLog(
      customLogger,
      () =>
        publishMessageService.publishMessage(
          eventhubService.topicResults,
          resultCache,
        ),
      logOperationInfo,
      logOperationDetail,
    );
  } catch (error) {
    customLogger.error(
      `Plant ${data.plant} Error processing message: ${error.message}`,
      context,
      error.stack,
    );
  }

  logOperationInfo.name = 'processData runtime';
  await execAndLog(
    customLogger,
    async () => {},
    logOperationInfo,
    logOperationDetail,
    startTime,
  );
}

parentPort?.on('message', async (data) => {
  await processData(data);
});

import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { Piscina } from 'piscina';
import { WorkersService } from './workers.service';
import { ApiModule } from '@/api/api.module';
import { LoggerConfigModule } from '@/config/logger/logger-config.module';
import { LoggerConfigService } from '@/config/logger/logger-config.service';
import { ThreadConfigModule } from '@/config/thread-config/thread-config.module';
import { ThreadConfigService } from '@/config/thread-config/thread-config.service';

@Module({
  exports: [WorkersService],
  imports: [ConfigModule, ApiModule, LoggerConfigModule, ThreadConfigModule],
  providers: [
    WorkersService,
    {
      inject: [LoggerConfigService, ThreadConfigService],
      provide: 'Piscina',
      useFactory: async (
        loggerConfigService: LoggerConfigService,
        threadConfigService: ThreadConfigService,
      ): Promise<Piscina> => {
        const filePath = `${process.cwd()}/dist/workers/worker.js`; // Path to worker file
        const logLevel = await loggerConfigService.lvlMpLogLevel();
        // Get options from the Redis client (casting is necessary)
        return new Piscina({
          filename: filePath,
          maxThreads: await threadConfigService.maxThreads(),
          workerData: { config: { logLevel } },
        });
      },
    },
  ],
})
export class WorkersModule {}

import { JobsLogContext } from '@mesx/common-lib';
import { Inject, Injectable } from '@nestjs/common';
import { Piscina } from 'piscina';
import { AppLogger } from '@/common/logger/app-logger';
import { CacheTask } from '@/interface/cache-task';

@Injectable()
export class WorkersService {
  public constructor(
    @Inject('Piscina') private readonly piscina: Piscina, // Inject the Piscina instance
    private readonly customLogger: AppLogger,
  ) {}

  public async runTask(data: CacheTask): Promise<void> {
    const context: JobsLogContext = {
      method: 'runTask',
      service: 'WorkersService',
    };
    try {
      await this.piscina.run(data, { name: 'processData' });
    } catch (error) {
      this.customLogger.error(
        `Error initializing WorkersService ${data.plant} : ${error.message}`,
        context,
        error.stack,
      );
    }
  }
}

